return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'uk','project-id-version'=>'TranslatePress Multilingual','pot-creation-date'=>'2026-10-13T10:48:01+03:00','po-revision-date'=>'2026-10-13T10:48:01+03:00','x-generator'=>'TranslatePress build (community + OpenRouter), 2026-10-13','messages'=>['TranslatePress - DEV'=>'TranslatePress - DEV','https://translatepress.com/'=>'https://translatepress.com/','Experience a better way of translating your WordPress site using a visual front-end translation editor, with full support for WooCommerce and site builders.'=>'Спробуйте кращий спосіб перекладу вашого сайту WordPress за допомогою візуального редактора перекладу на фронтенді з повною підтримкою WooCommerce та конструкторів сайтів.','Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban'=>'Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban','https://cozmoslabs.com/'=>'https://cozmoslabs.com/','Active'=>'Активний','The inactive languages will still be visible and active for the admin. For other users they won\'t be visible in the language switchers and won\'t be accessible either.'=>'Неактивні мови залишатимуться видимими та активними для адміністратора. Для інших користувачів вони не відображатимуться в перемикачах мов і також не будуть доступні.','unknown'=>'невідомо','<strong>Extra Languages add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Додаток Extra Languages</strong> потребує TranslatePress версії %1$s або вищої. Зараз ви використовуєте версію %2$s. Будь ласка, оновіть TranslatePress, щоб увімкнути цю функцію.','Dismiss this notice.'=>'Приховати це сповіщення.','Post Slug'=>'Slug запису','URL Slugs Translation'=>'Переклад slug URL','Slugs'=>'Slug','Taxonomy Slugs'=>'Slug таксономій','Search Taxonomy Slugs'=>'Пошук slug таксономій','Taxonomy Slug'=>'Slug таксономії','Translation'=>'Переклад','Term Slugs'=>'Slug термінів','Search Term Slugs'=>'Пошук slug термінів','Term Slug'=>'Slug терміна','Taxonomy'=>'Таксономія','Filter by Taxonomy'=>'Фільтрувати за таксономією','Post Slugs'=>'Slug записів','Search Post Slugs'=>'Пошук slug записів','Post ID'=>'ID запису','Post Type'=>'Тип запису','Filter by Post Type'=>'Фільтр за типом запису','Published'=>'Опубліковано','Any Post Status'=>'Будь-який статус запису','Post Type Base Slugs'=>'Базові slug типів записів','Post Type Base Slug'=>'Базовий slug типу запису','Search Post Type Base Slugs'=>'Пошук базових slug типів записів','WooCommerce Slugs'=>'WooCommerce slug','WooCommerce Slug'=>'WooCommerce slug','Search WooCommerce Slugs'=>'Пошук slug WooCommerce','Automatic and manual slug translation changes performed when <strong>TranslatePress - Multilingual</strong> 2.8.4 was active had to be removed because of some issues with that version. All slug translations from before that version are now in use. Thank you for understanding!'=>'Автоматичні та ручні зміни перекладу slug, виконані під час активної роботи <strong>TranslatePress - Multilingual</strong> 2.8.4, було видалено через деякі проблеми з цією версією. Усі переклади slug з попередніх версій тепер використовуються. Дякуємо за розуміння!','If you absolutely need them, the removed translations can be found in tables trp_slug_original_obsolete and trp_slug_translation_obsolete.'=>'Якщо вони вам абсолютно необхідні, видалені переклади можна знайти в таблицях trp_slug_original_obsolete та trp_slug_translation_obsolete.','(inactive)'=>'(неактивний)','Other Slugs'=>'Інші slug','Search Other Slugs'=>'Пошук інших slug','Automatic User Language Detection'=>'Автоматичне визначення мови користувача','Invalid language code'=>'Неприпустимий код мови','We\'ve detected you might be speaking a different language. Do you want to change to:'=>'Ми виявили, що ви, можливо, розмовляєте іншою мовою. Бажаєте змінити на:','Change Language'=>'Змінити мову','Close and do not switch language'=>'Закрити і не перемикати мову','First by browser language, then IP address (recommended)'=>'Спочатку за мовою браузера, потім за IP-адресою (рекомендовано)','First by IP address, then by browser language'=>'Спочатку за IP-адресою, потім за мовою браузера','Only by browser language'=>'Лише за мовою браузера','Only by IP address'=>'Лише за IP-адресою','A popup appears asking the user if they want to be redirected'=>'З’являється спливаюче вікно з питанням, чи хоче користувач бути перенаправленим','Redirect directly (*not recommended)'=>'Перенаправляти безпосередньо (*не рекомендується)','Pop-up window over the content'=>'Спливаюче вікно над вмістом','Hello bar before the content'=>'Панель сповіщень перед вмістом','Automatic User Language Detection requires a newer version of TranslatePress to use its visual settings interface. The legacy settings form will remain available until TranslatePress is updated.'=>'Для використання візуального інтерфейсу налаштувань Автоматичного визначення мови користувача потрібна новіша версія TranslatePress. Форма застарілих налаштувань залишатиметься доступною, доки TranslatePress не буде оновлено.','Update TranslatePress'=>'Оновити TranslatePress','WARNING. Cannot determine your language preference based on your current IP.<br>This is most likely because the website is on a local environment.'=>'УВАГА. Неможливо визначити ваші мовні вподобання на основі поточної IP-адреси.<br>Це, найімовірніше, тому що вебсайт розташовано в локальному середовищі.','Permission denied.'=>'У доступі відмовлено.','Invalid nonce.'=>'Недійсний nonce.','Invalid settings.'=>'Недійсні налаштування.','Settings saved.'=>'Налаштування збережено.','Go to <a href="%s" target="_self">Advanced</a> tab to change this feature\'s settings'=>'Перейдіть на вкладку <a href="%s" target="_self">Розширені</a>, щоб змінити налаштування цієї функції','Website language selector'=>'Перемикач мови веб-сайту','Change language'=>'Змінити мову','Available languages'=>'Доступні мови','Please enter your DeepL API key.'=>'Введіть свій ключ API DeepL.','DeepL'=>'DeepL','Bad request. There was an error accessing the DeepL API.'=>'Неправильний запит. Під час доступу до DeepL API сталася помилка.','The API key entered is invalid.'=>'Введений ключ API недійсний.','The API resource could not be found.'=>'Ресурс API не знайдено.','The request size is too large.'=>'Розмір запиту завеликий.','The request is too long.'=>'Запит занадто довгий.','Too many requests. Please try again later.'=>'Занадто багато запитів. Спробуйте пізніше.','Your translation quota has been reached.'=>'Вашу квоту перекладів вичерпано.','We could not process your request. Please try again later.'=>'Не вдалося обробити ваш запит. Спробуйте пізніше.','There is an error on the DeepL service and your request could not be processed.'=>'У сервісі DeepL сталася помилка, і ваш запит не вдалося обробити.','DeepL API Type'=>'Тип API DeepL','Pro'=>'Pro','Free'=>'Free','Select the type of DeepL API you want to use.'=>'Виберіть тип API DeepL, який ви хочете використовувати.','DeepL API Key'=>'Ключ API DeepL','Visit <a href="%s" target="_blank">this link</a> to see how you can set up an API key and control API costs.'=>'Відвідайте <a href="%s" target="_blank">це посилання</a>, щоб дізнатися, як налаштувати ключ API та керувати витратами на API.','No Active License Detected for this website.'=>'Для цього веб-сайту не виявлено активної ліцензії.','Enter your license key'=>'Введіть ключ ліцензії',' Or %1$spurchase one here%2$s'=>' Або %1$sпридбайте її тут%2$s','Different Domain per Language'=>'Окремий домен для кожної мови','View Docs'=>'Переглянути документацію','Assign different domains or subdomains to each language. When visitors access these domains, TranslatePress loads the appropriate language translation directly without redirecting.'=>'Призначити різні домени або субдомени для кожної мови. Коли відвідувачі заходять на ці домени, TranslatePress завантажує відповідний переклад відповідною мовою безпосередньо без перенаправлення.','Example: %1$s for English, %2$s for Spanish, %3$s for French.'=>'Приклад: %1$s для англійської, %2$s для іспанської, %3$s для французької.','Before enabling:'=>'Перед увімкненням:','Ensure your domains are registered, pointed to your server, and have SSL certificates configured.'=>'Переконайтеся, що ваші домени зареєстровані, спрямовані на ваш сервер і мають налаштовані SSL-сертифікати.','Domain'=>'Домен','Map this language to a different domain or sub-domain.'=>'Прив’яжіть цю мову до іншого домену або піддомену.','https://example.com'=>'https://example.com','Prefill with current domain'=>'Заповнити поточним доменом','Check DNS'=>'Перевірити DNS','Checking DNS...'=>'Перевірка DNS...','DNS is correctly configured!'=>'DNS налаштовано правильно!','DNS check failed. Please verify your domain configuration.'=>'Перевірка DNS не вдалася. Будь ласка, перевірте конфігурацію домену.','This domain is already assigned to another language.'=>'Цей домен уже прив’язаний до іншої мови.','<strong>Different Domain per Language add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Додаток «Різний домен для кожної мови»</strong> вимагає версії TranslatePress %1$s або вищої. Зараз ви використовуєте версію %2$s. Будь ласка, оновіть TranslatePress, щоб увімкнути цю функцію.','Note: This option is disabled when Different Domain for Language addon is active.'=>'Примітка: цю опцію вимкнено, коли активний додаток «Різний домен для кожної мови».','Different Domain per Language: Domain is required when domain mapping is enabled. The toggle has been disabled for languages with empty domains.'=>'Різний домен для кожної мови: домен обов’язковий, якщо увімкнено прив’язку домену. Перемикач вимкнено для мов із порожніми доменами.','Different Domain per Language: The same domain cannot be assigned to multiple languages. The toggle has been disabled for duplicate domains.'=>'Різний домен для кожної мови: один і той самий домен не можна призначати кільком мовам. Перемикач вимкнено для дублікатів доменів.','Different Domain per Language: A language domain cannot be the same as the main site URL. The toggle has been disabled for the matching domain.'=>'Різний домен для кожної мови: домен мови не може збігатися з основною URL-адресою сайту. Перемикач вимкнено для відповідного домену.','Please enter a domain.'=>'Будь ласка, введіть домен.','Invalid domain format.'=>'Неправильний формат домену.','Could not reach domain: %s'=>'Не вдалося отримати доступ до домену: %s','Domain is reachable!'=>'Домен доступний!','Domain returned HTTP status %d.'=>'Домен повернув HTTP-статус %d.','Limit this menu item to the following languages'=>'Обмежити цей пункт меню такими мовами','All Languages'=>'Усі мови','Translator'=>'Перекладач',' TranslatePress Settings'=>' Налаштування TranslatePress','Allow this user to translate the website.'=>'Дозволити цьому користувачу перекладати сайт.','Translate Site'=>'Перекласти сайт','Add-On'=>'Додаток','Deactivate'=>'Деактивувати','Activate'=>'Активувати','Installing...'=>'Встановлення...','This add-on can not be activated back without a valid license. Are you sure you want to deactivate it?'=>'Цей додаток не можна буде активувати знову без дійсної ліцензії. Ви впевнені, що хочете його деактивувати?','Documentation'=>'Документація','A valid license is required to activate add-ons.'=>'Для активації додатків потрібна дійсна ліцензія.','Activate all'=>'Активувати всі','Add-ons can not be activated back without a valid license. Are you sure you want to deactivate them?'=>'Додатки не можна буде активувати знову без дійсної ліцензії. Ви впевнені, що хочете їх деактивувати?','Deactivate all'=>'Деактивувати всі','%1$sAdd-ons settings saved successfully%2$s'=>'%1$sНалаштування додатків успішно збережено%2$s','Date format'=>'Формат дати','Customize the date formatting per each translated language.<br/>Leave empty for default WP setting or see more information <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">here</a>'=>'Налаштувати формат дати для кожної перекладеної мови.<br/>Залишити порожнім для типового налаштування WP або переглянути додаткову інформацію <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">тут</a>','To edit an existing TranslatePress language, input the language code and fill in only the columns you want to overwrite (e.g. Language name, Flag).<br>You can also add new custom languages. They will be available under General settings, All Languages list, where the URL slug can be edited.'=>'Щоб редагувати наявну мову TranslatePress, введіть код мови та заповніть лише ті стовпці, які хочете перезаписати (наприклад, назва мови, прапор).<br>Ви також можете додати нові користувацькі мови. Вони будуть доступні в розділі Загальні налаштування, у списку Усі мови, де можна редагувати URL slug.','For custom flag, first upload the image in media library then paste the URL.<br>Changing or deleting a custom language will impact translations and site URL\'s.<br>The Language code and the ISO Code should contain only alphabetical values, numerical values, "-" and "_".<br>The ISO Codes can be found on <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Google ISO Codes</a> and <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">DeepL Target Codes</a>.'=>'Для власного прапора спочатку завантажте зображення до медіабібліотеки, а потім вставте URL.<br>Зміна або видалення власної мови вплине на переклади та URL сайту.<br>Код мови та ISO-код мають містити лише літери, цифри, «-» та «_».<br>ISO-коди можна знайти на <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Google ISO Codes</a> та <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">DeepL Target Codes</a>.','Language code'=>'Код мови','Language name'=>'Назва мови','Native name'=>'Рідна назва','ISO Code'=>'ISO-код','Flag URL'=>'URL прапора','Text RTL'=>'Текст справа наліво','Custom language'=>'Власна мова','Disable bundled plugin translations'=>'Вимкнути вбудовані переклади плагіна','By default, TranslatePress ships its own translation files in <code>wp-content/plugins/translatepress/languages/</code> and forces WordPress to use them instead of the language packs installed automatically from translate.wordpress.org.<br/>Enable this option to disable that override. WordPress will then load the community language pack from <code>wp-content/languages/plugins/</code> (if present) and fall back to the bundled files only when no pack is available.'=>'За замовчуванням TranslatePress постачає власні файли перекладу в <code>wp-content/plugins/translatepress/languages/</code> і змушує WordPress використовувати їх замість мовних пакетів, що автоматично інсталюються з translate.wordpress.org.<br/>Увімкніть цю опцію, щоб вимкнути це перевизначення. Тоді WordPress завантажуватиме мовний пакет спільноти з <code>wp-content/languages/plugins/</code> (за наявності) і використовуватиме вбудовані файли лише за відсутності пакета.','Disable dynamic translation'=>'Вимкнути динамічний переклад','It disables detection of strings displayed dynamically using JavaScript. <br/>Strings loaded via a server side AJAX call will still be translated.'=>'Вимикає виявлення рядків, що динамічно відображаються за допомогою JavaScript. <br/>Рядки, завантажені через виклик AJAX на стороні сервера, все одно перекладатимуться.','Disable translation for gettext strings'=>'Вимкнути переклад для рядків gettext','Gettext Strings are strings outputted by themes and plugins. <br> Translating these types of strings through TranslatePress can be unnecessary if they are already translated using the .po/.mo translation file system.<br>Enabling this option can improve the page load performance of your site in certain cases. The disadvantage is that you can no longer edit gettext translations using TranslatePress, nor benefit from automatic translation on these strings.'=>'Рядки Gettext — це рядки, які виводяться темами та плагінами. <br> Переклад цих типів рядків через TranslatePress може бути зайвим, якщо вони вже перекладені за допомогою системи файлів перекладу .po/.mo.<br>Увімкнення цієї опції може покращити швидкість завантаження сторінок вашого сайту в певних випадках. Недолік полягає в тому, що ви більше не зможете редагувати переклади gettext за допомогою TranslatePress, а також не зможете скористатися автоматичним перекладом цих рядків.','Gettext Strings translation is disabled'=>'Переклад рядків Gettext вимкнено','To enable it go to '=>'Щоб увімкнути його, перейдіть до ','TranslatePress->Advanced Settings->Debug->Disable translation for gettext strings'=>'TranslatePress->Розширені налаштування->Налагодження->Вимкнути переклад для рядків gettext',' and uncheck the Checkbox.'=>' і зніміть позначку з прапорця.','Dismiss'=>'Відхилити','Exclude translated links from sitemap'=>'Виключити перекладені посилання з sitemap','Do not include translated links in sitemaps generated by SEO plugins.<br/>Requires <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> SEO Pack Add-on</a> to be installed and activated.'=>'Не включати перекладені посилання у sitemaps, згенерованих плагінами SEO.<br/>Потребує, щоб <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> додаток SEO Pack</a> був встановлений та активований.','Disable post container tags for post title'=>'Вимкнути контейнерні теги для заголовка запису','It disables search indexing the post title in translated languages.<br/>Useful when the title of the post doesn\'t allow HTML thus breaking the page.'=>'Це вимикає індексацію заголовка запису в перекладених мовах.<br/>Корисно, коли заголовок запису не підтримує HTML, що призводить до помилки на сторінці.','Disable post container tags for post content'=>'Вимкнути контейнерні теги для вмісту запису','It disables search indexing the post content in translated languages.<br/>Useful when the content of the post doesn\'t allow HTML thus breaking the page.'=>'Це вимикає індексацію вмісту запису в перекладених мовах.<br/>Корисно, коли вміст запису не підтримує HTML, що призводить до помилки на сторінці.','Do not translate certain paths'=>'Не перекладати певні шляхи','Choose what paths can be translated. Supports wildcard at the end of the path.<br>For example, to exclude https://example.com/some/path you can either use the rule /some/path/ or /some/*.<br>Enter each rule on it\'s own line. To exclude the home page use {{home}}.'=>'Виберіть, які шляхи можна перекладати. Підтримує символ підстановки наприкінці шляху.<br>Наприклад, щоб виключити https://example.com/some/path, ви можете використати правило /some/path/ або /some/*.<br>Вводьте кожне правило з нового рядка. Щоб виключити головну сторінку, використовуйте {{home}}.','Exclude Paths From Translation'=>'Виключити шляхи з перекладу','Translate Only Certain Paths'=>'Перекладати лише певні шляхи','Enable the hreflang x-default tag for language:'=>'Увімкнути тег hreflang x-default для мови:','Enables the hreflang="x-default" for an entire language. See documentation for more details.'=>'Вмикає hreflang="x-default" для всієї мови. Докладніше дивіться в документації.','Translate numbers and numerals'=>'Перекладати числа та цифри','Enable translation of numbers ( e.g. phone numbers)'=>'Увімкнути переклад чисел ( наприклад, номерів телефонів)','Selector'=>'Селектор','Exclude from dynamic translation'=>'Виключити з динамічного перекладу','Do not dynamically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated using JavaScript.<br/>These strings will still be translated on the server side if possible.'=>'Не перекладати динамічно рядки, що знаходяться у вузлах html, які відповідають цим селекторам.<br>Виключає з перекладу за допомогою JavaScript усі дочірні елементи вузлів HTML, що відповідають цим селекторам.<br/>Ці рядки все одно будуть перекладені на стороні сервера, якщо це можливо.','Gettext String'=>'Рядок Gettext','Exclude Gettext Strings'=>'Виключити рядки Gettext','Exclude these strings from being translated as Gettext strings by TranslatePress. Leave the domain empty to take into account any Gettext string.<br/>Can still be translated through po/mo files.'=>'Виключити ці рядки з перекладу як рядки Gettext за допомогою TranslatePress. Залиште домен порожнім, щоб врахувати будь-який рядок Gettext.<br/>Їх все ще можна перекласти за допомогою файлів .po/.mo.','Exclude selectors only from automatic translation'=>'Виключити селектори лише з автоматичного перекладу','Do not automatically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being automatically translated.<br>Manual translation of these strings is still possible.'=>'Не перекладати автоматично рядки, що знаходяться у вузлах html, які відповідають цим селекторам.<br>Виключає з автоматичного перекладу всі дочірні елементи вузлів HTML, що відповідають цим селекторам.<br>Ручний переклад цих рядків все ще можливий.','Exclude selectors from translation'=>'Виключити селектори з перекладу','Do not translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated.<br>These strings cannot be translated manually nor automatically.'=>'Не перекладати рядки, що знаходяться у вузлах html, які відповідають цим селекторам.<br>Виключає з перекладу всі дочірні елементи вузлів HTML, що відповідають цим селекторам.<br>Ці рядки не можна перекласти ні вручну, ні автоматично.','String'=>'Рядок','Exclude strings from automatic translation'=>'Виключити рядки з автоматичного перекладу','Do not automatically translate these strings (ex. names, technical words...)<br>Paragraphs containing these strings will still be translated except for the specified part.'=>'Не перекладати автоматично ці рядки (наприклад, імена, технічні терміни...)<br>Абзаци, що містять ці рядки, все одно будуть перекладені, окрім зазначеної частини.','Fix broken HTML'=>'Виправити пошкоджений HTML','General attempt to fix broken or missing HTML on translated pages.<br/>'=>'Загальна спроба виправити пошкоджений або відсутній HTML на перекладених сторінках.<br/>','Force slash at end of home url:'=>'Примусово додавати слеш у кінці домашнього URL:','Ads a slash at the end of the home_url() function'=>'Додає слеш у кінці функції home_url()','Show Both (recommended)'=>'Показувати обидва (рекомендовано)','Remove Country Locale'=>'Вилучити локаль країни','Remove Region Independent Locale'=>'Вилучити локаль без регіону','Remove duplicate hreflang'=>'Вилучити дублікати hreflang','Choose which hreflang tags will appear on your website.<br/>We recommend showing both types of hreflang tags as indicated by <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">Google documentation</a>.<br/>Removing Country Locale when having multiple Country Locales of the same language (ex. English UK and English US) will result in showing one hreflang tag with link to just one of the region locales for that language.'=>'Оберіть, які теги hreflang відображатимуться на вашому сайті.<br/>Рекомендуємо показувати обидва типи тегів hreflang, як зазначено в <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">документації Google</a>.<br/>Вилучення локалі країни за наявності кількох локалей країн однієї мови (наприклад, English UK та English US) призведе до відображення одного тегу hreflang із посиланням лише на одну з регіональних локалей цієї мови.','Default (example: en-US, fr-CA, etc.)'=>'За замовчуванням (приклад: en-US, fr-CA тощо)','Regional (example: en, fr, es, etc.)'=>'Регіональний (приклад: en, fr, es тощо)','HTML Lang Attribute Format'=>'Формат атрибута lang HTML','Change lang attribute of the html tag to a format that includes country regional or not. <br>In HTML, the lang attribute (<html lang="en-US">)  should be used to  specify the language of text content so that the  browser can correctly display or process  your content (eg. for  hyphenation, styling, spell checking, etc).'=>'Змініть атрибут lang тега html на формат, що включає країну/регіон чи ні. <br>У HTML атрибут lang (<html lang="en-US">) слід використовувати для зазначення мови текстового вмісту, щоб браузер міг правильно відображати або обробляти ваш вміст (наприклад, для перенесення, стилізації, перевірки правопису тощо).','Load legacy Language Switcher'=>'Завантажувати застарілий перемикач мови','Applies to all types of language switchers (floating, shortcode, and menu). When enabled, the site will revert to using the original Language Switcher configured in the General Settings tab, replacing the new customizable version. Your existing switcher settings will remain saved, but they will be ignored while this option is active.'=>'Застосовується до всіх типів перемикачів мови (плаваючий, shortcode та меню). Якщо ввімкнено, сайт повернеться до використання оригінального перемикача мови, налаштованого на вкладці «Загальні налаштування», замінивши нову настроювану версію. Ваші наявні налаштування перемикача залишаться збереженими, але їх буде проігноровано, поки ця опція активна.','Load legacy SEO Pack Add-On'=>'Завантажувати застарілий додаток SEO Pack','In case the recent migration to the new slug rewrite is causing trouble, set this to Yes to use the old method <br> Please <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">open a support ticket</a> letting us know of the issues you are having.'=>'Якщо нещодавня міграція на новий перезапис slug спричиняє проблеми, встановіть це значення Так, щоб використовувати старий метод <br> Будь ласка, <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">відкрийте тікет підтримки</a>, повідомивши нас про проблеми, з якими ви зіткнулися.','Manual Translation Only'=>'Лише ручний переклад','TranslatePress pro-actively scans and saves strings in the database when users access translated pages. <br>This setting disables this functionality and only allows translation and string saving when inside the Translation Editor. <br>Also disables machine translation outside the Translation Editor, giving you better control over character spending, by translating only the pages you visit in the Translation Editor.'=>'TranslatePress проактивно сканує та зберігає рядки в базі даних, коли користувачі відвідують перекладені сторінки. <br>Це налаштування вимикає цю функціональність і дозволяє перекладати та зберігати рядки лише в Редакторі перекладів. <br>Також вимикає машинний переклад поза Редактором перекладів, надаючи кращий контроль над витратою символів, перекладаючи лише сторінки, які ви відвідуєте в Редакторі перекладів.','Open language switcher only on click'=>'Відкривати перемикач мови лише по кліку','Open the language switcher shortcode by clicking on it instead of hovering.<br> Close it by clicking on it, anywhere else on the screen or by pressing the escape key. This will affect only the shortcode language switcher.'=>'Відкривати перемикач мови shortcode клацанням замість наведення.<br> Закривати його клацанням по ньому, клацанням у будь-якому іншому місці екрана або натисканням клавіші Escape. Це вплине лише на перемикач мови shortcode.','Show opposite language in the language switcher'=>'Показувати протилежну мову в перемикачі мови','Transforms the language switcher into a button showing the other available language, not the current one.<br> Only works when there are exactly two languages, the default one and a translation one.<br>This will affect the shortcode language switcher and floating language switcher as well.<br> To achieve this in menu language switcher go to Appearance->Menus->Language Switcher and select Opposite Language.'=>'Перетворює перемикач мови на кнопку, що показує іншу доступну мову, а не поточну.<br> Працює лише тоді, коли є рівно дві мови: мова за замовчуванням та мова перекладу.<br>Це вплине також на перемикач мови shortcode та плаваючий перемикач мови.<br> Щоб досягти цього в перемикачі мови меню, перейдіть у Зовнішній вигляд->Меню->Перемикач мови та виберіть Протилежну мову.','TranslatePress gettext database optimization failed.'=>'Не вдалося виконати оптимізацію бази даних gettext TranslatePress.','Retry'=>'Повторити','TranslatePress needs to optimize its gettext database tables. Back up the database, then <a href="%s">start the optimization</a>.'=>'TranslatePress потрібно оптимізувати таблиці бази даних gettext. Створіть резервну копію бази даних, а потім <a href="%s">почніть оптимізацію</a>.','Pending gettext database optimization'=>'Очікується оптимізація бази даних gettext','Optimize TranslatePress database tables'=>'Оптимізувати таблиці бази даних TranslatePress','<a href="%s">Click here</a> to access the database optimization tool.'=>'<a href="%s">Натисніть тут</a>, щоб отримати доступ до інструмента оптимізації бази даних.','It helps remove possible duplicate translations, clear unnecessary data and repair possible metadata issues.'=>'Це допомагає видалити можливі дублікати перекладів, очистити непотрібні дані та виправити можливі проблеми з метаданими.','<a href="%s" target="_blank">Here</a> you can observe the last 5 SQL errors relevant to TranslatePress if they exist.'=>'<a href="%s" target="_blank">Тут</a> ви можете переглянути останні 5 помилок SQL, пов’язаних із TranslatePress, якщо вони є.','Troubleshooting'=>'Вирішення проблем','Exclude Gettext strings'=>'Виключити рядки Gettext','Debug'=>'Налагодження','Custom languages'=>'Користувацькі мови','Miscellaneous options'=>'Різні налаштування','Language Switcher'=>'Перемикач мови','Exclude strings & pages'=>'Виключити рядки та сторінки','Automatic Translation Memory'=>'Автоматична пам\'ять перекладів','Serve same translation for similar text. The strings need to have a percentage of 95% similarity.<br>Helps prevent losing existing translation when correcting typos or making minor adjustments to the original text. <br>If a translation already exists for a very similar original string, it will automatically be used for the current original string.<br>Does not work when making changes to a text that is part of a translation block unless the new text is manually merged again in a translation block.<br>Each string needs to have a minimum of 50 characters.'=>'Використовувати той самий переклад для схожого тексту. Рядки мають мати 95% схожості.<br>Допомагає запобігти втраті наявного перекладу під час виправлення помилок або незначних змін оригінального тексту. <br>Якщо переклад для дуже схожого оригінального рядка вже існує, його буде автоматично використано для поточного оригінального рядка.<br>Не працює під час внесення змін до тексту, який є частиною блоку перекладу, якщо новий текст не буде повторно об’єднано в блоці перекладу вручну.<br>Кожен рядок має містити щонайменше 50 символів.','WARNING: This feature can negatively impact page loading times in secondary languages, particularly with large databases (for example websites with a lot of pages or products). If you experience slow loading times, disable this and try again.'=>'ПОПЕРЕДЖЕННЯ: Ця функція може негативно вплинути на час завантаження сторінок додатковими мовами, особливо з великими базами даних (наприклад, веб-сайти з великою кількістю сторінок або товарів). Якщо у вас спостерігається повільне завантаження, вимкніть це та спробуйте знову.','Fix missing dynamic content'=>'Виправити відсутній динамічний вміст','May help fix missing content inserted using JavaScript. <br> It shows dynamically inserted content in original language for a moment before the translation request is finished.'=>'Може допомогти виправити відсутній вміст, вставлений за допомогою JavaScript. <br> Показує динамічно вставлений вміст оригінальною мовою на мить до завершення запиту перекладу.','Filter Gettext wrapping from post content and title'=>'Фільтрувати обгортання Gettext із вмісту та заголовка запису','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post content and post title. Does not affect previous post content. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Фільтрує обгортання gettext, такі як #!trpst#trp-gettext, з усього оновленого вмісту та заголовків записів. Не впливає на попередній вміст записів. <br/><strong>Перед увімкненням рекомендується створити резервну копію бази даних.</strong>','Filter Gettext wrapping from post meta'=>'Фільтрувати обгортання Gettext із метаданих запису','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post meta. Does not affect previous post meta. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Фільтрує обгортання gettext, такі як #!trpst#trp-gettext, з усіх оновлених метаданих записів. Не впливає на попередні метадані записів. <br/><strong>Перед увімкненням рекомендується створити резервну копію бази даних.</strong>','TranslatePress'=>'TranslatePress','Abilities for managing TranslatePress configuration.'=>'Можливості керування конфігурацією TranslatePress.','Add a translation language'=>'Додати мову перекладу','Adds a translation language to TranslatePress. Enforces the same per-license limit as the settings UI.'=>'Додає мову перекладу до TranslatePress. Застосовує таке саме обмеження на ліцензію, як і інтерфейс налаштувань.','WordPress locale code (e.g. fr_FR, de_DE).'=>'Код локалі WordPress (наприклад, fr_FR, de_DE).','Optional URL slug. Defaults to the ISO language code if omitted.'=>'Необов\'язковий URL slug. За замовчуванням використовується код мови ISO, якщо не вказано.','Set TranslatePress license key'=>'Встановити ліцензійний ключ TranslatePress','Saves a TranslatePress license key and triggers a remote license check, mirroring the onboarding flow.'=>'Зберігає ліцензійний ключ TranslatePress та ініціює віддалену перевірку ліцензії, відтворюючи процес початкового налаштування.','The license key to activate.'=>'Ліцензійний ключ для активації.','Enable Automatic Translation'=>'Увімкнути автоматичний переклад','Turns on Automatic Translation. A valid TranslatePress license is required only when the resolved engine is TranslatePress AI (mtapi); Google Translate and DeepL do not require one. If no engine is passed and none is configured, defaults to mtapi.'=>'Вмикає автоматичний переклад. Дійсна ліцензія TranslatePress потрібна лише тоді, коли вибрано рушій TranslatePress AI (mtapi); Google Translate і DeepL не потребують ліцензії. Якщо рушій не вказано та не налаштовано, за замовчуванням використовується mtapi.','Optional translation-engine slug to select (e.g. "mtapi", "google_translate_v2", "deepl"). When omitted, keeps the already-configured engine, or defaults to "mtapi" if none is configured.'=>'Необов’язковий слаг рушія перекладу для вибору (наприклад, «mtapi», «google_translate_v2», «deepl»). Якщо пропущено, залишає вже налаштований рушій або за замовчуванням використовує «mtapi», якщо рушій не налаштовано.','List configured languages'=>'Перелік налаштованих мов','Returns the languages currently configured in TranslatePress, including the default language and per-language slug/publish state.'=>'Повертає мови, які наразі налаштовані в TranslatePress, включно з мовою за замовчуванням, а також slug і станом публікації для кожної мови.','List available language codes'=>'Перелік доступних кодів мов','Returns the full catalog of language codes TranslatePress recognizes, with their English names.'=>'Повертає повний каталог кодів мов, які розпізнає TranslatePress, із їхніми англійськими назвами.','Remove a translation language'=>'Видалити мову перекладу','Removes a configured translation language. The default language cannot be removed without first reassigning the default.'=>'Видаляє налаштовану мову перекладу. Мову за замовчуванням неможливо видалити без попереднього переназначення мови за замовчуванням.','Locale code of the language to remove.'=>'Код локалі мови, яку потрібно видалити.','Update a translation language'=>'Оновити мову перекладу','Replaces the slug and publish status of an already-configured translation language.'=>'Замінює slug та статус публікації вже налаштованої мови перекладу.','Locale code of the language to update.'=>'Код локалі мови, яку потрібно оновити.','URL slug for this language.'=>'URL slug для цієї мови.','Whether this language is published on the front end.'=>'Чи опубліковано цю мову на фронтенді.','Set the default language'=>'Встановити мову за замовчуванням','Promotes an already-configured language to be the site default. The previous default remains in the translation languages list.'=>'Призначає вже налаштовану мову мовою за замовчуванням сайту. Попередня мова за замовчуванням залишається у списку мов перекладу.','Locale code to promote to default. Must already be a configured translation language.'=>'Код локалі для призначення мовою за замовчуванням. Має вже бути налаштованою мовою перекладу.','You do not have permission to manage TranslatePress settings.'=>'У вас немає дозволу керувати налаштуваннями TranslatePress.','Invalid language code. Allowed characters: A-Z, a-z, 0-9, hyphen, underscore.'=>'Неприпустимий код мови. Дозволені символи: A-Z, a-z, 0-9, дефіс, підкреслення.','Language code "%s" is not recognized by TranslatePress.'=>'Код мови "%s" не розпізнається TranslatePress.','Language "%s" is already configured.'=>'Мову "%s" вже налаштовано.','Your current license allows up to %d additional language(s). Upgrade or activate a Pro license to add more.'=>'Максимальна кількість додаткових мов за вашою поточною ліцензією: %d. Оновіть або активуйте ліцензію Pro, щоб додати більше.','TranslatePress rejected the new language during settings sanitization.'=>'TranslatePress відхилив нову мову під час очищення налаштувань.','Enabling Automatic Translation with the TranslatePress AI engine requires an active TranslatePress license. Activate a license first with translatepress/set-license-key, or pass a different engine (e.g. "google_translate_v2", "deepl").'=>'Увімкнення автоматичного перекладу з рушієм TranslatePress AI потребує активної ліцензії TranslatePress. Спочатку активуйте ліцензію за допомогою translatepress/set-license-key або вкажіть інший рушій (наприклад, «google_translate_v2», «deepl»).','Your license key expired on %s.'=>'Термін дії вашого ліцензійного ключа закінчився %s.','Your license key has expired.'=>'Термін дії вашого ліцензійного ключа закінчився.','Your license key has been disabled.'=>'Ваш ліцензійний ключ було вимкнено.','Your TranslatePress license key is invalid or missing.'=>'Ваш ліцензійний ключ TranslatePress недійсний або відсутній.','Your license key is disabled for this URL. Re-enable it from your TranslatePress account.'=>'Ваш ліцензійний ключ вимкнено для цього URL. Увімкніть його знову у вашому обліковому записі TranslatePress.','License key mismatch. The license you entered does not match the TranslatePress version you have installed.'=>'Невідповідність ліцензійного ключа. Введена вами ліцензія не відповідає версії TranslatePress, яку ви встановили.','Your license key has reached its activation limit.'=>'Ваш ліцензійний ключ досяг ліміту активацій.','An error occurred while activating the license, please try again.'=>'Під час активації ліцензії сталася помилка, спробуйте ще раз.','Language "%s" is not currently configured.'=>'Мову "%s" зараз не налаштовано.','The default language cannot be removed. Set another language as default first.'=>'Мову за замовчуванням не можна видалити. Спочатку встановіть іншу мову за замовчуванням.','Slug is empty after sanitization. Use only URL-safe characters.'=>'Slug порожній після очищення. Використовуйте лише безпечні для URL символи.','Language "%s" is not currently configured. Add it first with translatepress/add-language.'=>'Мову "%s" зараз не налаштовано. Спочатку додайте її за допомогою translatepress/add-language.','The default language is always published and cannot be unpublished.'=>'Мова за замовчуванням завжди опублікована, і її не можна зняти з публікації.','Slug "%1$s" is already in use by language "%2$s".'=>'Slug "%1$s" вже використовується мовою "%2$s".','TranslatePress rejected the new settings during sanitization.'=>'TranslatePress відхилив нові налаштування під час очищення.','Advanced'=>'Розширені','Are you sure you want to remove this item?'=>'Ви впевнені, що хочете видалити цей елемент?','Remove'=>'Видалити','Add'=>'Додати','Select...'=>'Вибрати...','An error occurred, please try again.'=>'Сталася помилка, будь ласка, спробуйте ще раз.','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Ваш ліцензійний ключ вимкнено для цього URL. Увімкніть його знову на <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Керування сайтами.','<p><strong>License key mismatch.</strong> The license you entered doesn’t match the TranslatePress version you have installed.</p><p>Please check that you’ve installed the correct version for your license from your TranslatePress account.</p>'=>'<p><strong>Невідповідність ліцензійного ключа.</strong> Введена вами ліцензія не відповідає встановленій версії TranslatePress.</p><p>Будь ласка, перевірте, що ви встановили правильну версію для вашої ліцензії з вашого облікового запису TranslatePress.</p>','If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'Якщо у вас встановлено лише безкоштовний плагін, але ви додали платну ліцензію, будь ласка, встановіть платний плагін з вашого облікового запису TranslatePress.','Upgrade your plan to add more sites. %1$sUpgrade now%2$s'=>'Оновіть ваш тарифний план, щоб додати більше сайтів. %1$sОновити зараз%2$s','You have successfully activated your license'=>'Ви успішно активували вашу ліцензію.','[%s] Low TranslatePress AI Words'=>'[%s] Мало слів TranslatePress AI','upgrade your plan'=>'оновити план','upgrade your plan or get extra AI Words'=>'оновити план або отримати додаткові слова AI','TranslatePress AI words are running low on your site.'=>'На вашому сайті закінчуються слова TranslatePress AI.','Current status: %s words remaining'=>'Поточний стан: залишилось %s слів','Once the remaining AI words run out, automatic translation through TranslatePress AI will be paused.'=>'Якщо залишок слів AI закінчиться, автоматичний переклад через TranslatePress AI буде призупинено.','To continue translating your content, please %1$s over at %2$s'=>'Щоб продовжити переклад вашого вмісту, будь ласка, %1$s на %2$s','Manage Notification: %s'=>'Керувати сповіщенням: %s','Others'=>'Інші','Restrict by Language'=>'Обмежити за мовою','Exclude from Language'=>'Виключити з мови','Restrict element to language'=>'Обмежити елемент мовою','Show this element only in one language.'=>'Показувати цей елемент лише на одній мові.','Enable translation'=>'Увімкнути переклад','Allow translation to the corresponding language only if the content is written in the default language.'=>'Дозволити переклад на відповідну мову лише за умови, що вміст написано мовою за замовчуванням.','Select language'=>'Вибрати мову','Choose in which language to show this element.'=>'Виберіть, якою мовою показувати цей елемент.','Exclude element from language'=>'Виключити елемент із мови','Exclude this element from specific languages.'=>'Виключити цей елемент із певних мов.','Select languages'=>'Вибрати мови','Choose from which languages to exclude this element.'=>'Виберіть, із яких мов виключити цей елемент.','This element will still be visible when you are translating your website through the Translation Editor.'=>'Цей елемент залишатиметься видимим під час перекладу вашого вебсайту в редакторі перекладів.','The content of this element should be written in the default language.'=>'Вміст цього елемента має бути написано мовою за замовчуванням.','<strong>TranslatePress</strong> encountered SQL errors. <a href="%s" title="View TranslatePress SQL Errors">Check out the errors</a>.'=>'<strong>TranslatePress</strong> виявив помилки SQL. <a href="%s" title="View TranslatePress SQL Errors">Перегляньте помилки</a>.','Automatic translation has been disabled.'=>'Автоматичний переклад вимкнено.','Logged errors'=>'Зареєстровані помилки','These are the most recent 5 errors logged by TranslatePress:'=>'Це 5 останніх помилок, зареєстрованих TranslatePress:','Yes'=>'Так','Why are these errors occuring'=>'Чому виникають ці помилки','If TranslatePress detects something wrong when executing queries on your database, it may disable the Automatic Translation feature in order to avoid any extra charging by Google/DeepL. Automatic Translation needs to be manually turned on, after you solve the issues.'=>'Якщо TranslatePress виявить щось не так під час виконання запитів до вашої бази даних, він може вимкнути функцію автоматичного перекладу, щоб уникнути додаткових стягнень коштів з боку Google/DeepL. Автоматичний переклад потрібно ввімкнути вручну після вирішення проблем.','The SQL errors detected can occur for various reasons including missing tables, missing permissions for the SQL user to create tables or perform other operations, problems after site migration or changes to SQL server configuration.'=>'Виявлені помилки SQL можуть виникати з різних причин, зокрема через відсутність таблиць, відсутність дозволів для користувача SQL на створення таблиць або виконання інших операцій, проблеми після міграції сайту або зміни конфігурації сервера SQL.','What you can do in this situation'=>'Що ви можете зробити в цій ситуації','Plan A.'=>'План А.','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL settings. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Перейдіть до Налаштування -> TranslatePress -> вкладка Загальні та Збережіть налаштування. Це відновить таблиці з використанням ваших поточних налаштувань SQL. Перевірте, чи не виникає більше помилок під час перегляду вашого веб-сайту перекладеною мовою. Зверніть увагу на позначки часу помилок, щоб переконатися, що ви бачите не старі помилки. Відображаються лише 5 найновіших помилок.','Plan B.'=>'План Б.','If your problem isn\'t solved, try the following steps:'=>'Якщо вашу проблему не вирішено, спробуйте виконати такі кроки:','Create a backup of your database'=>'Створіть резервну копію вашої бази даних','Create a copy of each translation table where you encounter errors. You can copy the table within the same database (trp_dictionary_en_us_es_es_COPY for example) -- perform this step only if you want to keep the current translations'=>'Створіть копію кожної таблиці перекладів, у якій ви зіткнулися з помилками. Ви можете скопіювати таблицю в межах тієї самої бази даних (наприклад, trp_dictionary_en_us_es_es_COPY) — виконуйте цей крок лише якщо ви хочете зберегти поточні переклади','Remove the trouble tables by executing the DROP function on them'=>'Видаліть проблемні таблиці, виконавши на них функцію DROP','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL server.'=>'Перейдіть до Налаштування -> TranslatePress -> вкладка Загальні та Збережіть налаштування. Це відновить таблиці з використанням вашого поточного сервера SQL.','Copy the relevant content from the duplicated tables (trp_dictionary_en_us_es_es_COPY for example) in the newly generated table (trp_dictionary_en_us_es_es) -- perform this step only if you want to keep the current translations'=>'Скопіюйте відповідний вміст із дубльованих таблиць (наприклад, trp_dictionary_en_us_es_es_COPY) у щойно створену таблицю (trp_dictionary_en_us_es_es) — виконуйте цей крок лише якщо ви хочете зберегти поточні переклади','Test it to see if everything is working. If something went wrong, you can restore the backup that you\'ve made at the first step. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Перевірте, чи все працює. Якщо щось пішло не так, ви можете відновити резервну копію, яку ви створили на першому кроці. Перевірте, чи не виникає більше помилок під час перегляду вашого веб-сайту перекладеною мовою. Зверніть увагу на позначки часу помилок, щоб переконатися, що ви бачите не старі помилки. Відображаються лише 5 найновіших помилок.','Plan C.'=>'План В.','If your problem still isn\'t solved, try asking your hosting about your errors. The most common issue is missing permissions for the SQL user, such as the Create Tables permission.'=>'Якщо вашу проблему досі не вирішено, спробуйте звернутися до свого хостинг-провайдера щодо ваших помилок. Найпоширенішою проблемою є відсутність дозволів для користувача SQL, зокрема дозволу на створення таблиць.','Could not install. Try again from <a href="%s" >Plugins Dashboard.</a>'=>'Не вдалося встановити. Повторіть спробу в <a href="%s" >панелі керування плагінами.</a>','Settings scope unknown.'=>'Область налаштувань невідома.','Legacy disabled.'=>'Застарілий режим вимкнено.','Change language to %s'=>'Змінити мову на %s','Automatic Translation'=>'Автоматичний переклад','Unsupported languages'=>'Непідтримувані мови','The selected automatic translation engine does not provide support for these languages.<br>You can still manually translate pages in these languages using the Translation Editor.'=>'Вибраний механізм автоматичного перекладу не підтримує ці мови.<br>Ви все ще можете перекладати сторінки цими мовами вручну за допомогою Редактора перекладів.','General'=>'Загальні','Glossary'=>'Глосарій','API key validation failed.'=>'Перевірку ключа API не виконано.','API key verification was successful.'=>'Перевірку ключа API успішно виконано.','Please enter your Google Translate key.'=>'Введіть свій ключ Google Translate.','Not TranslatePress onboarding page.'=>'Це не сторінка онбордингу TranslatePress.','Step %s does not exist'=>'Крок %s не існує','Welcome'=>'Вітаємо','Add Languages'=>'Додати мови','Enable Addons'=>'Увімкнути додатки','Finalize'=>'Завершити','Exit Setup'=>'Вийти з налаштування','Upgrade'=>'Покращити','Nothing here'=>'Тут нічого немає','Your <strong>TranslatePress</strong> license is missing or invalid. <br/>Please %1$sregister your copy%2$s to enable automatic website translation via TranslatePress AI, premium addons, automatic updates and support. Need a license key? %3$sPurchase one now%4$s'=>'Ваша ліцензія <strong>TranslatePress</strong> відсутня або недійсна. <br/>Будь ласка, %1$sзареєструйте свою копію%2$s, щоб увімкнути автоматичний переклад сайту через TranslatePress AI, преміум-доповнення, автоматичні оновлення та підтримку. Потрібен ліцензійний ключ? %3$sПридбайте його зараз%4$s','Your license is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Ваша ліцензія вимкнена для цього URL. Увімкніть її знову в <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Керування сайтами.','You have reached the activation limit for your <strong>%1$s</strong> license. <br/>Manage your active sites from %2$s your account %3$s.'=>'Ви досягли ліміту активації для вашої ліцензії <strong>%1$s</strong>. <br/>Керуйте своїми активними сайтами з %2$s вашого облікового запису %3$s.','License key mismatch. The license you entered doesn’t match the <strong>%1$s</strong> version you have installed. <br/>Please check that you’ve installed the correct version for your license from your %2$sTranslatePress account%3$s.'=>'Невідповідність ліцензійного ключа. Введена вами ліцензія не відповідає версії <strong>%1$s</strong>, яку ви встановили. <br/>Будь ласка, перевірте, чи ви встановили правильну версію для вашої ліцензії з вашого %2$sоблікового запису TranslatePress%3$s.','<br/>If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'<br/>Якщо у вас встановлено лише безкоштовний плагін, але ви додали платну ліцензію, будь ласка, встановіть платний плагін з вашого облікового запису TranslatePress.','Your <strong>TranslatePress</strong> license has expired. <br/>Please %1$sRenew Your Licence%2$s to continue receiving access to automatic translations via TranslatePress AI, premium addons, product downloads, and automatic updates. %3$sRenew now %4$s'=>'Ваша ліцензія <strong>TranslatePress</strong> закінчилася. <br/>Будь ласка, %1$sоновіть свою ліцензію%2$s, щоб і надалі мати доступ до автоматичних перекладів через TranslatePress AI, преміум-доповнень, завантажень продуктів та автоматичних оновлень. %3$sОновити зараз %4$s','Error: '=>'Помилка: ','Something went wrong, please try again.'=>'Щось пішло не так, будь ласка, спробуйте ще раз.','Your <strong>TranslatePress</strong> license will expire on %1$s. Please %2$sRenew Your Licence%3$s to continue receiving access to automatic translations via TP AI, premium addons, product downloads and automatic updates. %4$sRenew Now%5$s'=>'Ваша ліцензія <strong>TranslatePress</strong> закінчується %1$s. Будь ласка, %2$sоновіть свою ліцензію%3$s, щоб і надалі мати доступ до автоматичних перекладів через TP AI, преміум-доповнень, завантажень продуктів та автоматичних оновлень. %4$sОновити зараз%5$s','Please %1$senter%2$s your license key to enable %3$s automatic translation.'=>'Будь ласка, %1$sвведіть%2$s ваш ліцензійний ключ, щоб увімкнути автоматичний переклад %3$s.','%1$s automatic translation requires an active license. Please %2$srenew%3$s your license or purchase a new one %4$shere%5$s.'=>'Для автоматичного перекладу %1$s потрібна активна ліцензія. Будь ласка, %2$sоновіть%3$s вашу ліцензію або придбайте нову %4$sтут%5$s.','You have less than 5,000 TranslatePress AI words remaining. To continue automatically translating your website, please %spurchase additional AI words at a discount from your account%s.'=>'У вас залишилося менше ніж 5000 слів TranslatePress AI. Щоб продовжити автоматичний переклад вашого сайту, будь ласка, %sпридбайте додаткові слова AI зі знижкою в вашому обліковому записі%s.','You do not have a valid license for <strong>TranslatePress</strong>. %1$sGet one for free%2$s to get access to TranslatePress AI.'=>'У вас немає дійсної ліцензії для <strong>TranslatePress</strong>. %1$sОтримайте її безкоштовно%2$s, щоб отримати доступ до TranslatePress AI.',' Error: '=>' Помилка: ','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Learn more</a>.'=>'<strong>НОВЕ:</strong> Доповнення <strong>Different Domain per Language</strong> вже тут! Покращіть свою глобальну SEO та створіть локалізований досвід за допомогою доменів для конкретних країн, як-от .de або .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Дізнатися більше</a>.','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. Upgrade to <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business or Developer</a> to access it + more premium perks!'=>'<strong>НОВЕ:</strong> Доповнення <strong>Different Domain per Language</strong> вже тут! Покращіть свою глобальну SEO та створіть локалізований досвід за допомогою доменів для конкретних країн, як-от .de або .fr. Перейдіть на <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business або Developer</a>, щоб отримати до нього доступ + інші преміум-переваги!','The daily quota for machine translation characters exceeded. Please check the <strong>TranslatePress -> <a href="%s">Automatic Translation</a></strong> page for more information.'=>'Перевищено денну квоту символів машинного перекладу. Будь ласка, перевірте сторінку <strong>TranslatePress -> <a href="%s">Автоматичний переклад</a></strong> для отримання додаткової інформації.','Marketing optin'=>'Маркетингова підписка','Opt in to our security and feature updates notifications, and non-sensitive diagnostic tracking.'=>'Дайте згоду на отримання сповіщень про оновлення безпеки та функцій, а також на збір нечутливих діагностичних даних.','TranslatePress Preferred User Language'=>'Бажана мова користувача TranslatePress','Preferred language to navigate the site'=>'Бажана мова для перегляду сайту','The language is automatically set based by the last visited language by the user.'=>'Мова автоматично встановлюється відповідно до останньої мови, обраної користувачем.','Always use this language'=>'Завжди використовувати цю мову','By checking this setting the preferred language will remain the one selected above, without the possibility of being changed in the frontend.<br>This language will be used in different operations such as sending email to the user.'=>'Якщо ввімкнути цей параметр, бажана мова залишатиметься такою, як обрано вище, без можливості зміни на сайті.<br>Ця мова використовуватиметься в різних операціях, наприклад під час надсилання електронних листів користувачу.','Hello! Seems like you\'ve been using <strong>TranslatePress</strong> for a while now to translate your website. That\'s awesome! '=>'Привіт! Схоже, ви вже деякий час використовуєте <strong>TranslatePress</strong> для перекладу свого сайту. Це чудово! ','If you can spare a few moments to rate it on WordPress.org it would help us a lot (and boost my motivation).'=>'Якщо ви знайдете кілька хвилин, щоб оцінити його на WordPress.org, це дуже нам допоможе (і підвищить мою мотивацію).','~ Razvan, developer of TranslatePress'=>'~ Разван, розробник TranslatePress','Rate TranslatePress on WordPress.org plugin page'=>'Оцінити TranslatePress на сторінці плагіна WordPress.org','Ok, I will gladly help!'=>'Гаразд, я з радістю допоможу!','No, thanks.'=>'Ні, дякую.','Full Language Names'=>'Повні назви мов','Short Language Names'=>'Короткі назви мов','Flags with Full Language Names'=>'Прапорці з повними назвами мов','Flags with Short Language Names'=>'Прапорці з короткими назвами мов','Only Flags'=>'Лише прапорці','Full Language Names No HTML'=>'Повні назви мов без HTML','Bottom Right'=>'Знизу справа','Bottom Left'=>'Знизу зліва','Top Right'=>'Зверху справа','Top Left'=>'Зверху зліва','Dark'=>'Темна','Light'=>'Світла','Install & Activate'=>'Встановити та активувати','Invalid language code. Please try again.'=>'Неприпустимий код мови. Спробуйте ще раз.','Language codes can contain only A-Z a-z 0-9 - _ characters. Check your language codes in TranslatePress General Settings.'=>'Коди мови можуть містити лише символи A-Z a-z 0-9 - _. Перевірте коди мови в загальних налаштуваннях TranslatePress.','Error! Duplicate URL slug values.'=>'Помилка! Дубльовані значення URL slug.','You cannot select two languages that have the same <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">iso code</a> but different formalities because doing so will lead to duplicate <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">hreflang tags</a>.'=>'Ви не можете вибрати дві мови, які мають однаковий <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">код ISO</a>, але різні формальності, оскільки це призведе до дублювання <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">тегів hreflang</a>.','Duplicate language detected.<br>Each language can only be added once to ensure accurate translation management.<br> Please change the duplicate language entry and try again. '=>'Виявлено дублікат мови.<br>Кожну мову можна додати лише один раз, щоб забезпечити точне керування перекладами.<br> Змініть дубльований запис мови та спробуйте ще раз. ','Current Language'=>'Поточна мова','Opposite Language'=>'Протилежна мова','Addons'=>'Додатки','Settings'=>'Налаштування','Pro Features'=>'Професійні функції','Activate License'=>'Активувати ліцензію','Need Help?'=>'Потрібна допомога?','Recent community discussions'=>'Останні обговорення спільноти','Loading...'=>'Завантаження...','Unable to load forum posts'=>'Не вдалося завантажити дописи форуму','Ask a Question'=>'Поставити запитання','View All Topics'=>'Переглянути всі теми','by'=>'від','Have a question?'=>'Маєте запитання?','Get help directly from the plugin developers, suggest improvements, or share your feedback!'=>'Отримайте допомогу безпосередньо від розробників плагіна, запропонуйте покращення або поділіться відгуком!','Tip for faster help:'=>'Порада для швидшої допомоги:','Include what you tried, what you expected, and what happened. Screenshots help!'=>'Вкажіть, що ви спробували, чого очікували та що сталося. Скріншоти допомагають!','Toggle support chat'=>'Перемкнути чат підтримки','Ask the community'=>'Запитати спільноту','Close'=>'Закрити','Empty feed response'=>'Порожня відповідь стрічки','Unable to parse feed'=>'Не вдалося розібрати стрічку','Just now'=>'Щойно','%d hour ago'=>'%d годину тому' . "\0" . '%d години тому' . "\0" . '%d годин тому','%d day ago'=>'%d день тому' . "\0" . '%d дні тому' . "\0" . '%d днів тому','Source'=>'Джерело','Srcset'=>'Srcset','Alt attribute'=>'Атрибут alt','Title attribute'=>'Атрибут title','Anchor link'=>'Якірне посилання','Placeholder attribute'=>'Атрибут placeholder','Submit attribute'=>'Атрибут submit','Text'=>'Текст','Video Poster'=>'Постер відео','plural form'=>'Форма множини','one'=>'один','few'=>'декілька','many'=>'багато','other'=>'інше','Saved'=>'Збережено','Save'=>'Зберегти','Saving translation...'=>'Збереження перекладу...','You have unsaved changes!'=>'У вас є незбережені зміни!','Discard changes'=>'Відкинути зміни','Discard All'=>'Відкинути все','Loading Strings...'=>'Завантаження рядків...','Select string to translate...'=>'Виберіть рядок для перекладу...','Close Editor'=>'Закрити редактор','From'=>'З','To'=>'На','Add Media'=>'Додати медіа','Other languages'=>'Інші мови','Context'=>'Контекст','View Website As'=>'Переглянути сайт як','Available in our Pro Versions'=>'Доступно в наших Pro-версіях','Select or Upload Media'=>'Виберіть або завантажте медіа','Use this media'=>'Використати це медіа','Translate'=>'Перекласти','Translate entire block element'=>'Перекласти весь блок','Split block to translate strings individually'=>'Розділити блок, щоб перекладати рядки окремо','Save changes to translation. Shortcut: CTRL(⌘) + S'=>'Зберегти зміни перекладу. Комбінація: CTRL(⌘) + S','Navigate to next string in dropdown list. Shortcut: CTRL(⌘) + ALT + Right Arrow'=>'Перейти до наступного рядка у спадному списку. Швидкий доступ: CTRL(⌘) + ALT + стрілка вправо','Navigate to previous string in dropdown list. Shortcut: CTRL(⌘) + ALT + Left Arrow'=>'Перейти до попереднього рядка у спадному списку. Швидкий доступ: CTRL(⌘) + ALT + стрілка вліво','Discard all changes. Shortcut: CTRL(⌘) + ALT + Z'=>'Скасувати всі зміни. Комбінація: CTRL(⌘) + ALT + Z','Discard changes to this text box. To discard changes to all text boxes use shortcut: CTRL(⌘) + ALT + Z'=>'Скасувати зміни в цьому текстовому полі. Щоб скасувати зміни в усіх текстових полях, використовуйте комбінацію: CTRL(⌘) + ALT + Z','Dismiss tooltip'=>'Закрити підказку','Quick Intro'=>'Коротке ознайомлення','Are you sure you want to split this phrase into smaller parts?'=>'Ви впевнені, що хочете розбити цю фразу на менші частини?','This string is not ready for translation yet. <br>Try again in a moment...'=>'Цей рядок ще не готовий до перекладу. <br>Спробуйте знову за мить...','For this option to work, please update the Browse as other role add-on to the latest version.'=>'Щоб ця опція працювала, оновіть додаток Browse as other role до останньої версії.','To translate slugs, please update the SEO Pack add-on to the latest version.'=>'Щоб перекладати slug, оновіть додаток SEO Pack до останньої версії.','You can add a new language from <a href="%s">Settings->TranslatePress</a>'=>'Ви можете додати нову мову на сторінці <a href="%s">Налаштування->TranslatePress</a>','However, you can still use TranslatePress to <strong style="background: #f5fb9d;">modify gettext strings</strong> available in your page.'=>'Проте ви все ще можете використовувати TranslatePress, щоб <strong style="background: #f5fb9d;">змінювати рядки gettext</strong>, доступні на вашій сторінці.','Strings that are user-created cannot be modified, only those from themes and plugins.'=>'Рядки, створені користувачем, не можна змінювати, лише ті, що з тем і плагінів.','Extra Translation Features'=>'Додаткові функції перекладу','Support for 130+ Extra Languages'=>'Підтримка 130+ додаткових мов','Access to TranslatePress AI'=>'Доступ до TranslatePress AI','Translate SEO Title, Description, Slug'=>'Перекласти SEO заголовок, опис та slug','Publish only when translation is complete'=>'Публікувати лише після завершення перекладу','Translate by Browsing as User Role'=>'Перекладати, переглядаючи як роль користувача','Different Menu Items for each Language'=>'Різні елементи меню для кожної мови','Upgrade to PRO'=>'Оновити до PRO','Upgrade to PRO with our biggest discount of the year!'=>'Оновіть до PRO з нашою найбільшою знижкою року!','This Black Friday, get access to these features and more at a fraction of the costs:'=>'Цієї Чорної п\'ятниці отримайте доступ до цих функцій та інших за частку вартості:','No available suggestions'=>'Немає доступних пропозицій','Suggestions from translation memory'=>'Пропозиції з пам\'яті перекладів','Click to Copy'=>'Натисніть, щоб скопіювати','Human Translation'=>'Людський переклад','Machine Translation'=>'Машинний переклад','Gettext File Translation'=>'Переклад файлів Gettext','Text on this page is %s% translated into all languages.'=>'Текст на цій сторінці перекладено на всі мови на %s%.','%1$s% of text on this page is translated into %2$s.'=>'%1$s% тексту на цій сторінці перекладено %2$s.','This page is %1$s% translated into %2$s.'=>'Ця сторінка перекладена %2$s на %1$s%.','The slug that you are trying to edit is present in other slug types:%s%. Editing it will replace each occurrence, regardless of the current type.'=>'slug, який ви намагаєтесь редагувати, присутній в інших типах slug:%s%. Редагування замінить кожне входження, незалежно від поточного типу.','Hover any text on the page, click %s,<br> then modify the translation in the sidebar.'=>'Наведіть курсор на будь-який текст на сторінці, натисніть %s,<br> а потім змініть переклад у бічній панелі.','Don\'t forget to Save Translation. Use keyboard shortcut CTRL(⌘) + S'=>'Не забудьте зберегти переклад. Використовуйте комбінацію клавіш CTRL(⌘) + S','Switch language to see the translation changes directly on the page.'=>'Змініть мову, щоб побачити зміни перекладу безпосередньо на сторінці.','Search for any text in this page in the dropdown.'=>'Шукайте будь-який текст на цій сторінці у випадному списку.','Your %s license has <span class="trp-license-status-emphasized">expired</span>.'=>'Ваша ліцензія %s <span class="trp-license-status-emphasized">прострочена</span>.','<strong>This Black Friday, renew your license at a special price</strong> to continue receiving access to product downloads, automatic updates, and support.'=>'<strong>Цьої Чорної п\'ятниці поновіть свою ліцензію за спеціальною ціною</strong>, щоб і надалі мати доступ до завантажень продуктів, автоматичних оновлень і підтримки.','Get Deal'=>'Отримати пропозицію','Please renew your license to continue receiving access to TranslatePress AI, premium addons, automatic updates and support.'=>'Будь ласка, поновіть свою ліцензію, щоб і надалі мати доступ до TranslatePress AI, преміум-додатків, автоматичних оновлень і підтримки.','Renew Now'=>'Поновити зараз','Your %s license was <span class="trp-license-status-emphasized">refunded</span>.'=>'Ваша ліцензія %s була <span class="trp-license-status-emphasized">повернена</span>.','Please purchase a new license to continue receiving access to TranslatePress AI, premium addons, automatic updates and support.'=>'Будь ласка, придбайте нову ліцензію, щоб і надалі мати доступ до TranslatePress AI, преміум-додатків, автоматичних оновлень і підтримки.','Purchase a new license'=>'Придбати нову ліцензію','Your %s license is <span class="trp-license-status-emphasized">missing or invalid</span>.'=>'Ваша ліцензія %s <span class="trp-license-status-emphasized">відсутня або недійсна</span>.','Please enter a valid license to get access to TranslatePress AI, premium addons, automatic updates and support. Need a license key? %1$sPurchase one now%2$s'=>'Будь ласка, введіть дійсну ліцензію, щоб отримати доступ до TranslatePress AI, преміум-додатків, автоматичних оновлень і підтримки. Потрібен ключ ліцензії? %1$sПридбати зараз%2$s','Enter a valid license'=>'Введіть дійсну ліцензію','Meta Information'=>'Метаінформація','String List'=>'Список рядків','Gettext Strings'=>'Рядки Gettext','Images'=>'Зображення','Videos'=>'Відео','Audios'=>'Аудіо','Dynamically Added Strings'=>'Динамічно додані рядки','Translation Editor'=>'Редактор перекладів','Edit translations by visually selecting them on each site page'=>'Редагуйте переклади, візуально вибираючи їх на кожній сторінці сайту','String Translation'=>'Переклад рядків','Edit url slug translations, plugins and theme translation (emails, forms etc.)'=>'Редагувати переклади URL slug, плагінів і тем (листи, форми тощо)','Current User'=>'Поточний користувач','Logged Out'=>'Вийшов із системи','Translate Page'=>'Перекласти сторінку','Add a New Language'=>'Додати нову мову','Your License is Invalid'=>'Ваша ліцензія недійсна','Get More AI Words (%d left)'=>'Отримати більше AI-слів (залишилося %d)','Opens post in the translation editor. Post must be saved as draft or published beforehand.'=>'Відкриває допис у редакторі перекладу. Допис має бути заздалегідь збережений як чернетка або опублікований.','Security check'=>'Перевірка безпеки','<strong>Warning:</strong> Some strings have possibly incorrectly encoded characters. This may result in breaking the queries, rendering the page untranslated in live mode. Consider revising the following strings or their method of outputting.'=>'<strong>Попередження:</strong> Деякі рядки містять символи з можливо некоректним кодуванням. Це може призвести до пошкодження запитів, і сторінка залишиться неперекладеною в робочому режимі. Рекомендуємо переглянути наведені нижче рядки або спосіб їх виведення.','IMPORTANT: It is strongly recommended to first backup the database!'=>'ВАЖЛИВО: наполегливо рекомендується спочатку створити резервну копію бази даних!','Are you sure you want to continue?'=>'Ви впевнені, що хочете продовжити?','TranslatePress data update'=>'Оновлення даних TranslatePress','We need to update your translations database to the latest version.'=>'Потрібно оновити базу даних перекладів до останньої версії.','Updating will allow editing translations of localized text from plugins and theme. Existing translation will still work as expected.'=>'Оновлення дозволить редагувати переклади локалізованого тексту з плагінів і теми. Наявні переклади й надалі працюватимуть як і раніше.','Run the updater'=>'Запустити оновлення','Updating will allow editing translations of slugs. Existing translation will still work as expected.'=>'Оновлення дозволить редагувати переклади ярликів. Існуючий переклад і надалі працюватиме належним чином.','Please activate the SEO Addon from <br/>WordPress -> Settings -> TranslatePress -> Addons section'=>'Будь ласка, активуйте додаток SEO на сторінці<br/>WordPress -> Налаштування -> TranslatePress -> Додатки','Go to Addons'=>'Перейти до Додатків','The SEO Pack add-on allows translation of all the URL slugs:'=>'Додаток SEO Pack дозволяє перекладати всі URL-ярлики:','Taxonomy slugs'=>'Ярлики таксономій','Term slugs'=>'Ярлики термінів','Post slugs (this includes pages and custom post types)'=>'Ярлики записів (сюди входять сторінки та користувацькі типи записів)','Post type base slugs'=>'Базові ярлики типів записів','WooCommerce slugs'=>'Ярлики WooCommerce','The SEO Pack add-on is available with ALL premium versions of the plugin.'=>'Додаток SEO Pack доступний у всіх преміум-версіях плагіна.','Upgrade to Pro'=>'Оновити до Pro','Description'=>'Опис','Article Section'=>'Розділ статті','Article Tag'=>'Мітка статті','OG Title'=>'Заголовок OG','OG Site Name'=>'Назва сайту OG','OG Description'=>'Опис OG','OG Image Alt'=>'Альт зображення OG','Twitter Title'=>'Заголовок Twitter','Twitter Description'=>'Опис Twitter','Twitter Image Alt'=>'Альт зображення Twitter','Page Title'=>'Заголовок сторінки','Dublin Core Title'=>'Заголовок Dublin Core','Dublin Core Description'=>'Опис Dublin Core','OG Image'=>'Зображення OG','OG Image Secure URL'=>'Безпечний URL зображення OG','Twitter Image'=>'Зображення Twitter','Removing cdata dictionary strings for language %s...'=>'Видалення рядків словника cdata для мови %s...','Removing untranslated dictionary links for language %s...'=>'Видалення неперекладених посилань словника для мови %s...','Removing duplicated gettext strings for language %s...'=>'Видалення дубльованих рядків gettext для мови %s...','Removing duplicated dictionary strings for language %s...'=>'Видалення дубльованих рядків словника для мови %s...','Removing untranslated dictionary strings where translation is available for language %s...'=>'Видалення неперекладених рядків словника з наявним перекладом для мови %s...','Inserting original strings for language %s...'=>'Вставлення оригінальних рядків для мови %s...','Cleaning original strings table for language %s...'=>'Очищення таблиці оригінальних рядків для мови %s...','Updating original string ids for language %s...'=>'Оновлення ID оригінальних рядків для мови %s...','Regenerating original meta table for language %s...'=>'Перегенерація таблиці метаданих оригінальних рядків для мови %s...','Cleaning original meta table for language %s...'=>'Очищення таблиці метаданих оригінальних рядків для мови %s...','Replacing original id NULL with value for language %s...'=>'Заміна NULL ідентифікатора оригінального рядка на значення для мови %s...','Inserting gettext original strings for language %s...'=>'Вставлення оригінальних рядків gettext для мови %s...','Cleaning gettext original strings table for language %s...'=>'Очищення таблиці оригінальних рядків gettext для мови %s...','Updating gettext original string ids for language %s...'=>'Оновлення ID оригінальних рядків gettext для мови %s...','Starting gettext database optimization in the background...'=>'Розпочинається оптимізація бази даних gettext у фоновому режимі...','Migrating taxonomy and post type base slugs to new table structure...'=>'Міграція ярликів таксономій і базових ярликів типів записів до нової структури таблиці...','Migrating post slugs to new table structure for language %s...'=>'Міграція ярликів записів до нової структури таблиці для мови %s...','Migrating term slugs to new table structure for language %s...'=>'Міграція термінів slug до нової структури таблиць для мови %s...','Finishing up...'=>'Завершення...','TranslatePress needs to optimize gettext database tables. Translations continue to work while this runs in the background.'=>'TranslatePress потрібно оптимізувати таблиці бази даних gettext. Переклади продовжуватимуть працювати, поки це виконується у фоновому режимі.','Before starting, we strongly recommend creating a database backup.'=>'Перед початком ми наполегливо рекомендуємо створити резервну копію бази даних.','Start optimization'=>'Почати оптимізацію','Update aborted! Could not schedule gettext database optimization.'=>'Оновлення перервано! Не вдалося запланувати оптимізацію бази даних Gettext.','Database optimization did not complete successfully. We recommend restoring the original database or <a href="%s" >trying again.</a>'=>'Оптимізація бази даних завершилася невдало. Рекомендуємо відновити оригінальну базу даних або <a href="%s" >спробувати ще раз.</a>','Update aborted! Your user account doesn\'t have the capability to perform database updates.'=>'Оновлення перервано! Ваш обліковий запис не має повноважень для виконання оновлень бази даних.','Update aborted! Invalid nonce.'=>'Оновлення перервано! Недійсний nonce.','Back to TranslatePress Settings'=>'Повернутися до налаштувань TranslatePress','Successfully updated database!'=>'Базу даних успішно оновлено!','Updating database to version %s+'=>'Оновлення бази даних до версії %s+','Processing table for language %s...'=>'Обробка таблиці для мови %s...','Update aborted! Incorrect action.'=>'Оновлення перервано! Неправильна дія.','Update aborted! Start the gettext database optimization separately from the Advanced settings page.'=>'Оновлення перервано! Почніть оптимізацію бази даних Gettext окремо зі сторінки додаткових налаштувань.','Update aborted! Incorrect language code.'=>'Оновлення перервано! Неправильний код мови.',' done.'=>' виконано.','Update aborted while %1$s. SQL error: %2$s'=>'Оновлення перервано на етапі %1$s. Помилка SQL: %2$s','inserting original strings'=>'вставлення оригінальних рядків','checking original string insertion progress'=>'перевірка прогресу вставлення оригінальних рядків','cleaning duplicate original strings'=>'очищення дублікатів оригінальних рядків','updating original string IDs'=>'оновлення ID оригінальних рядків','checking original string ID update progress'=>'перевірка прогресу оновлення ID оригінальних рядків','inserting gettext original strings'=>'вставлення оригінальних рядків Gettext','checking gettext original insertion progress'=>'перевірка прогресу вставлення оригінальних рядків Gettext','cleaning duplicate gettext original strings'=>'очищення дублікатів оригінальних рядків Gettext','updating gettext original string IDs'=>'оновлення ID оригінальних рядків Gettext','checking gettext original string ID update progress'=>'перевірка прогресу оновлення ID оригінальних рядків Gettext','All individual TranslatePress add-on plugins <a href="%1$s" target="_blank">have been discontinued</a> and are now included in the premium Personal, Business and Developer versions of TranslatePress. Please log into your <a href="%2$s" target="_blank">account page</a>, download the new premium version and install it. Your individual addons settings will be ported over.'=>'Усі окремі плагіни-доповнення TranslatePress <a href="%1$s" target="_blank">були припинені</a> та тепер включені до преміум-версій TranslatePress Personal, Business і Developer. Будь ласка, увійдіть на свою <a href="%2$s" target="_blank">сторінку облікового запису</a>, завантажте нову преміум-версію та встановіть її. Ваші налаштування окремих доповнень буде перенесено.','Brand-new Language Switcher Settings are here!'=>'Зовсім нові налаштування перемикача мов вже тут!','Explore pre-made templates, switch colors, flag styles, spacing, layouts & more. Use the live preview to perfect your switcher in seconds.'=>'Ознайомтеся з готовими шаблонами, змінюйте кольори, стилі прапорів, відступи, макети та багато іншого. Використовуйте живий перегляд, щоб за лічені секунди вдосконалити свій перемикач.','Start customizing'=>'Почати налаштування','Read documentation'=>'Читати документацію','<strong>TranslatePress</strong> requires <strong><a href="http://php.net/manual/en/book.mbstring.php">Multibyte String PHP library</a></strong>. Please contact your server administrator to install it on your server.'=>'<strong>TranslatePress</strong> потребує <strong><a href="http://php.net/manual/en/book.mbstring.php">бібліотеки PHP для роботи з багатобайтовими рядками</a></strong>. Будь ласка, зв\'яжіться з адміністратором вашого сервера, щоб встановити її на сервері.','Detected long query limitation on WPEngine hosting. Some large pages may appear untranslated. You can remove limitation by adding the following to your site’s wp-config.php: define( \'WPE_GOVERNOR\', false ); '=>'Виявлено обмеження довгих запитів на хостингу WPEngine. Деякі великі сторінки можуть відображатися без перекладу. Ви можете зняти обмеження, додавши наступне до файлу wp-config.php вашого сайту: define( \'WPE_GOVERNOR\', false ); ','Custom Language Flag'=>'Прапорець власної мови','The Language code of the added custom language is invalid.'=>'Код доданої власної мови недійсний.','The Language code of the added custom language cannot be empty.'=>'Код доданої власної мови не може бути порожнім.','The Automatic Translation Code of the added custom language is invalid.'=>'Код автоматичного перекладу доданої власної мови недійсний.','Style'=>'Стиль','Use shortcode settings'=>'Використовувати налаштування shortcode','Custom'=>'Власне','Language names'=>'Назви мов','Full names'=>'Повні назви','Short names'=>'Короткі назви','Hide names'=>'Приховати назви','Flag position'=>'Позиція прапорця','Before text'=>'Перед текстом','After text'=>'Після тексту','Hide flags'=>'Приховати прапорці','Open on click'=>'Відкривати по кліку','Show opposite language'=>'Показувати протилежну мову','Size'=>'Розмір','Normal'=>'Звичайний','Large'=>'Великий','Flag shape'=>'Форма прапорця','Rectangle'=>'Прямокутник','Square'=>'Квадрат','Rounded'=>'Заокруглений','Transitions'=>'Переходи','Background'=>'Фон','Hover background'=>'Фон при наведенні','Hover text'=>'Текст при наведенні','Border color'=>'Колір рамки','Border width'=>'Ширина рамки','Border radius'=>'Радіус рамки','Flag radius'=>'Радіус прапорця','Disable the legacy TranslatePress language switcher to use the customizable Elementor widget. <a href="%s" target="_blank" rel="noopener noreferrer">Open language switcher settings</a>.'=>'Вимкніть застарілий перемикач мов TranslatePress, щоб використовувати налаштовуваний віджет Elementor. <a href="%s" target="_blank" rel="noopener noreferrer">Відкрити налаштування перемикача мов</a>.','The language switcher inherits styling options from shortcode. <a href="%s" target="_blank" rel="noopener noreferrer">Open shortcode settings</a>.'=>'Перемикач мов успадковує параметри стилю від shortcode. <a href="%s" target="_blank" rel="noopener noreferrer">Відкрити налаштування shortcode</a>.','TranslatePress AI'=>'TranslatePress AI','Your TranslatePress AI API Key is valid.'=>'Ваш ключ API TranslatePress AI дійсний.','Your TranslatePress AI API Key is invalid.'=>'Ваш ключ API TranslatePress AI недійсний.','Your TranslatePress AI API Key has expired.'=>'Ваш ключ API TranslatePress AI прострочений.','Activate API Key'=>'Активувати ключ API','Deactivate API Key'=>'Деактивувати ключ API','Add a TranslatePress AI API Key'=>'Додати ключ API TranslatePress AI','TranslatePress AI API Key'=>'Ключ API TranslatePress AI','Manage your TranslatePress AI API Key in your %1$s.'=>'Керуйте вашим ключем API TranslatePress AI у вашому %1$s.','Don’t have a TranslatePress AI API Key?'=>'Не маєте ключа API TranslatePress AI?','Get a free TranslatePress AI API Key Today'=>'Отримайте безкоштовний ключ API TranslatePress AI сьогодні','Add your TranslatePress AI API Key'=>'Додайте ваш ключ API TranslatePress AI','Add your TranslatePress AI API Key to unlock all premium features. Find the TranslatePress AI API Key in your'=>'Додайте ваш ключ API TranslatePress AI, щоб розблокувати всі преміум функції. Знайдіть ключ API TranslatePress AI у вашому','Your TranslatePress AI API Key is valid and active.'=>'Ваш ключ API TranslatePress AI дійсний і активний.','Activate TranslatePress AI API Key'=>'Активувати ключ API TranslatePress AI','No Active API Key Detected for this website.'=>'Для цього веб-сайту не виявлено активного ключа API.','In order to enable Automatic Translation using TranslatePress AI, you need an API key by creating a free account.'=>'Щоб увімкнути автоматичний переклад за допомогою TranslatePress AI, створіть безкоштовний обліковий запис, щоб отримати ключ API.','Enter your API key'=>'Введіть ваш ключ API','In order to enable Automatic Translation using TranslatePress AI, please enter your API key from'=>'Щоб увімкнути автоматичний переклад за допомогою TranslatePress AI, введіть ваш ключ API з','API Key'=>'Ключ API','No Active TranslatePress AI API Key Detected for this website.'=>'Для цього веб-сайту не виявлено активного ключа API TranslatePress AI.','Get Your Free TranslatePress AI API Key'=>'Отримайте безкоштовний ключ API TranslatePress AI','Generate API Key'=>'Згенерувати ключ API','You have a valid %s <strong>API Key</strong>.'=>'У вас є дійсний <strong>ключ API</strong> %s.','Manage your API Key & quota on the %s'=>'Керуйте своїм ключем API та квотою на %s','Get a Free AI API Key'=>'Отримати безкоштовний ключ API AI','This website is already activated under a free API key. Each website can only use one free API key.'=>'Цей веб-сайт уже активовано безкоштовним ключем API. Кожен веб-сайт може використовувати лише один безкоштовний ключ API.','This website is already activated under a free API key. Each website can only use one free API key. Please upgrade to a premium plan for more TranslatePress AI words from %1$s your account %2$s.'=>'Цей веб-сайт уже активовано безкоштовним ключем API. Кожен веб-сайт може використовувати лише один безкоштовний ключ API. Будь ласка, перейдіть на преміум-план, щоб отримати більше слів TranslatePress AI з %1$s вашого облікового запису %2$s.','Debug Data for API Key Checking'=>'Дані налагодження для перевірки ключа API','Debug Data for API Key Activation'=>'Дані налагодження для активації ключа API','TranslatePress finished replacing the existing translations in your dictionary.'=>'TranslatePress завершив заміну наявних перекладів у вашому словнику.','Term (%s)'=>'Термін (%s)','Translations'=>'Переклади','Term added. Glossary terms only affect new automatic translations.'=>'Термін додано. Терміни глосарія впливають лише на нові автоматичні переклади.','Term updated.'=>'Термін оновлено.','Term deleted.'=>'Термін видалено.','Are you sure you want to delete this term?'=>'Ви впевнені, що хочете видалити цей термін?','Something went wrong. Please try again.'=>'Щось пішло не так. Будь ласка, спробуйте ще раз.','Quick Edit'=>'Швидке редагування','Edit'=>'Редагувати','Delete'=>'Видалити','Update'=>'Оновити','Cancel'=>'Скасувати','No glossary terms match your search.'=>'Жоден термін глосарію не відповідає вашому пошуку.','No glossary terms found.'=>'Термінів глосарію не знайдено.','Could not load glossary terms. Please reload the page.'=>'Не вдалося завантажити терміни глосарію. Будь ласка, оновіть сторінку.','items'=>'елементів','of'=>'з','First page'=>'Перша сторінка','Previous page'=>'Попередня сторінка','Next page'=>'Наступна сторінка','Last page'=>'Остання сторінка','The inserted term was found in your existing translations, use the %s to make changes there.'=>'Вставлений термін знайдено у ваших існуючих перекладах. Скористайтеся %s, щоб внести там зміни.','search & replace tool'=>'інструмент пошуку та заміни','Please provide at least one existing translation to replace.'=>'Будь ласка, вкажіть принаймні один існуючий переклад для заміни.','You are about to bulk edit a potentially large amount of translations. This action cannot be undone. It is recommended to make a backup of the database before completing this action.'=>'Ви збираєтеся масово редагувати потенційно велику кількість перекладів. Цю дію неможливо скасувати. Рекомендується створити резервну копію бази даних перед завершенням цієї дії.','Continue with replacing existing translations?'=>'Продовжити заміну існуючих перекладів?','No entries found.'=>'Записів не знайдено.','Original'=>'Оригінал','Security check failed. Please reload the page and try again.'=>'Перевірку безпеки не пройдено. Будь ласка, оновіть сторінку та спробуйте знову.','You do not have permission to do this.'=>'У вас немає дозволу на виконання цієї дії.','Please enter the term in the default language.'=>'Будь ласка, введіть термін мовою за замовчуванням.','Please provide at least one translation for the term.'=>'Будь ласка, вкажіть принаймні один переклад для терміна.','The term “%s” already exists in the glossary.'=>'Термін «%s» вже існує в глосарії.','The term you are trying to edit no longer exists. Please reload the page.'=>'Термін, який ви намагаєтеся редагувати, більше не існує. Будь ласка, оновіть сторінку.','The term you are trying to delete no longer exists. Please reload the page.'=>'Термін, який ви намагаєтеся видалити, більше не існує. Будь ласка, оновіть сторінку.','%1$s: %2$d entry updated'=>'%1$s: %2$d запис оновлено' . "\0" . '%1$s: %2$d записи оновлено' . "\0" . '%1$s: %2$d записів оновлено','Replacement complete.'=>'Заміну завершено.','This is a large replacement. %d entries were updated now and the rest will finish automatically in the background over the next few minutes.'=>'Це велика заміна. Зараз оновлено %d записів, а решта завершиться автоматично у фоновому режимі протягом наступних кількох хвилин.','Google Translate v2'=>'Google Translate v2','Google Translate API Key'=>'Ключ API Google Translate','Add your API Key here...'=>'Додайте свій ключ API тут...','Visit <a href="https://cloud.google.com/docs/authentication/api-keys" target="_blank">this link</a> to see how you can set up an API key, <strong>control API costs</strong> and set HTTP referrer restrictions.'=>'Відвідайте <a href="https://cloud.google.com/docs/authentication/api-keys" target="_blank">це посилання</a>, щоб дізнатися, як налаштувати ключ API, <strong>контролювати витрати на API</strong> та встановити обмеження HTTP referrer.','Your HTTP referrer is: %s'=>'Ваш HTTP referrer: %s','There was an error with your Google Translate key.'=>'Сталася помилка з вашим ключем Google Translate.','There was an error on the server processing your Google Translate key.'=>'Сталася помилка на сервері під час обробки вашого ключа Google Translate.','Please check your TranslatePress license key.'=>'Будь ласка, перевірте ваш ліцензійний ключ TranslatePress.','Create your Free Account'=>'Створіть безкоштовний обліковий запис',' or '=>' або ','Your free account includes: '=>'Ваш безкоштовний обліковий запис включає: ','Access to TranslatePress AI for instant automatic translations'=>'Доступ до TranslatePress AI для миттєвих автоматичних перекладів','2000 AI words to translate automatically'=>'2000 слів для автоматичного перекладу','Get more AI Words and unlock all AI features with TranslatePress Pro.'=>'Отримайте більше AI-слів і розблокуйте всі AI-функції за допомогою TranslatePress Pro.','Upgrade now'=>'Оновити зараз','You have a valid %s <strong>license</strong>.'=>'У вас є дійсна <strong>ліцензія</strong> %s.',' words remaining. '=>' слів залишилося. ','Recheck'=>'Перевірити знову','Rechecking...'=>'Перевіряємо знову...','Done.'=>'Готово.','Manage your license & quota on the %s'=>'Керуйте своєю ліцензією та квотою на %s','TranslatePress.com Account Page'=>'Сторінка облікового запису TranslatePress.com','Advanced Add-ons'=>'Розширені додатки','These addons extend your translation plugin and are available in the Developer, Business and Personal plans.'=>'Ці додатки розширюють ваш плагін перекладу та доступні в тарифах Developer, Business і Personal.','SEO Pack'=>'SEO Pack','SEO support for page slug, page title, description and Facebook and Twitter social graph information. The HTML lang attribute is properly set.'=>'Підтримка SEO для slug сторінки, заголовка сторінки, опису та інформації соціального графа Facebook і Twitter. Атрибут HTML lang установлено правильно.','Multiple Languages'=>'Кілька мов','Add as many languages as you need for your project to go global. Publish your language only when all your translations are done.'=>'Додавайте стільки мов, скільки потрібно, щоб ваш проєкт став глобальним. Публікуйте мову лише тоді, коли всі переклади будуть готові.','Pro Add-ons'=>'Pro-додатки','These addons extend your translation plugin and are available in the Business and Developer plans.'=>'Ці додатки розширюють ваш плагін перекладу та доступні в тарифах Business і Developer.','DeepL Automatic Translation'=>'Автоматичний переклад DeepL','Automatically translate your website through the DeepL API.'=>'Автоматично перекладайте ваш сайт за допомогою DeepL API.','Prompts visitors to switch to their preferred language based on their browser settings or IP address and remembers the last visited language.'=>'Пропонує відвідувачам перейти на їхню бажану мову на основі налаштувань браузера або IP-адреси та запам’ятовує останню відвідану мову.','Translator Accounts'=>'Облікові записи перекладачів','Create translator accounts for new users or allow existing users that are not administrators to translate your website.'=>'Створюйте облікові записи перекладачів для нових користувачів або дозвольте існуючим користувачам, які не є адміністраторами, перекладати ваш сайт.','Browse As User Role'=>'Перегляд як роль користувача','Navigate your website just like a particular user role would. Really useful for dynamic content or hidden content that appears for particular users.'=>'Переглядайте свій сайт так, як це робила б певна роль користувача. Дуже корисно для динамічного контенту або прихованого контенту, який з’являється для певних користувачів.','Navigation Based on Language'=>'Навігація на основі мови','Configure different menu items for different languages.'=>'Налаштовуйте різні пункти меню для різних мов.','Connect separate domains or subdomains to each of your translated versions. Strengthen your brand’s local identity and boost SEO performance for every language you support.'=>'Підключіть окремі домени або субдомени до кожного перекладеного варіанту. Зміцніть локальну ідентичність свого бренду та покращіть SEO-показники для кожної мови, яку ви підтримуєте.','Enable Modules'=>'Увімкнути модулі','Enable Add-on modules to extend TranslatePress and enhance the functionality of your translated site.'=>'Увімкніть модулі-розширення, щоб розширити TranslatePress і покращити функціональність вашого перекладеного сайту.','TranslatePress Pro is active. Activate your license key to unlock the Pro add-ons below.'=>'TranslatePress Pro активний. Активуйте ліцензійний ключ, щоб розблокувати Pro-додатки нижче.','Activate license'=>'Активувати ліцензію','TranslatePress Pro is installed but not activated yet.'=>'TranslatePress Pro встановлено, але ще не активовано.','Opens your Plugins page (filtered to TranslatePress) in a new tab. Activate the TranslatePress Pro plugin there, then return to this tab — it will update automatically.'=>'Відкриває сторінку плагінів (відфільтровану за TranslatePress) у новій вкладці. Активуйте плагін TranslatePress Pro там, потім поверніться до цієї вкладки — вона оновиться автоматично.','Activate TranslatePress Pro ↗'=>'Активувати TranslatePress Pro ↗','More functionality with TranslatePress Pro.'=>'Більше функціональності з TranslatePress Pro.','Upgrade now ↗'=>'Оновити зараз ↗','Already a Pro User?'=>'Вже користувач Pro?','Opens the WordPress “Add Plugins” page in a new tab. Upload and activate the TranslatePress Pro plugin there, then return to this tab — it will update automatically.'=>'Відкриває сторінку WordPress «Додати плагіни» у новій вкладці. Завантажте та активуйте плагін TranslatePress Pro там, потім поверніться до цієї вкладки — вона оновиться автоматично.','Install TranslatePress Pro'=>'Встановити TranslatePress Pro','This add-on is not available on your current plan.'=>'Це розширення недоступне у вашому поточному тарифі.','Continue'=>'Продовжити','The link you followed has expired. Please reload the page and try again.'=>'Посилання, за яким ви перейшли, застаріло. Будь ласка, оновіть сторінку та спробуйте ще раз.','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=activate-license">https://translatepress.com/account</a> -> Manage Sites.'=>'Ваш ліцензійний ключ вимкнено для цього URL. Увімкніть його знову на <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=activate-license">https://translatepress.com/account</a> -> Керування сайтами.','<p><strong>License key mismatch.</strong> The license you entered doesn\'t match the TranslatePress version you have installed.</p><p>Please check that you\'ve installed the correct version for your license from your TranslatePress account.</p>'=>'<p><strong>Невідповідність ліцензійного ключа.</strong> Ліцензія, яку ви ввели, не відповідає встановленій версії TranslatePress.</p><p>Перевірте, чи встановлено правильну версію для вашої ліцензії з вашого облікового запису TranslatePress.</p>','TranslatePress Account'=>'TranslatePress Account','« Go Back'=>'« Назад','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=tp-ai">https://translatepress.com/account</a> -> Manage Sites.'=>'Ваш ліцензійний ключ вимкнено для цієї URL-адреси. Увімкніть його знову на <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=tp-ai">https://translatepress.com/account</a> -> Керування сайтами.','Automatically translate your website using TranslatePress AI.'=>'Автоматично перекладайте свій веб-сайт за допомогою TranslatePress AI.','your account.'=>'вашого облікового запису.','Skip and continue with manual translation »'=>'Пропустити та продовжити з ручним перекладом »','Creating a free account includes: '=>'Створення безкоштовного облікового запису включає: ','Are you a TranslatePress PRO user?'=>'Ви користувач TranslatePress PRO?','Install TranslatePress Pro.'=>'Встановити TranslatePress Pro.','Skip this step'=>'Пропустити цей крок','The email address you added is incorrect.'=>'Введена вами адреса електронної пошти некоректна.','Setup Complete'=>'Налаштування завершено','You\'re ready to start translating!'=>'Ви готові розпочати переклад!','You have successfully set up TranslatePress for your website.'=>'Ви успішно налаштували TranslatePress для свого веб-сайту.','Receive '=>'Отримувати ','Yes, send me multilingual growth tips.'=>'Так, надсилайте мені поради щодо багатомовного розвитку.','Start translating'=>'Почати переклад','Sign Up and Start translating'=>'Зареєструватися та почати переклад','You need to select a default language.'=>'Вам потрібно вибрати мову за замовчуванням.','You are trying to add an invalid default language. Please select a valid option.'=>'Ви намагаєтеся додати недійсну мову за замовчуванням. Будь ласка, виберіть дійсний варіант.','Please add an additional language.'=>'Будь ласка, додайте додаткову мову.','You are trying to add an invalid additional language. Please select a valid option.'=>'Ви намагаєтеся додати неприпустиму додаткову мову. Будь ласка, виберіть дійсний варіант.','Configure Site Languages'=>'Налаштувати мови сайту','Select the default and additional languages for your website.'=>'Виберіть мову за замовчуванням та додаткові мови для вашого веб-сайту.','You can edit your site languages at any point.'=>'Ви можете редагувати мови сайту в будь-який момент.','Default Language'=>'Мова за замовчуванням','Select the language your content is written in.'=>'Виберіть мову, якою написано ваш вміст.','Additional Language'=>'Додаткова мова','Choose a secondary language...'=>'Виберіть додаткову мову...','Slug'=>'Slug','Add Language'=>'Додати мову','Choose a language...'=>'Виберіть мову...','TranslatePress Pro is active. Activate your license key to add more languages.'=>'TranslatePress Pro активний. Активуйте ліцензійний ключ, щоб додати більше мов.','Add more than two languages with TranslatePress Pro.'=>'Додайте більше двох мов за допомогою TranslatePress Pro.','Set up Language Switcher'=>'Налаштувати перемикач мов','Select the style of the language switcher. You will find more ways to display it, in plugin settings.'=>'Виберіть стиль перемикача мов. Ви знайдете більше способів його відображення в налаштуваннях плагіна.','Displays a small language drop-down across your website, in a corner of your choosing.'=>'Відображає невеликий випадний список мов на всьому вашому веб-сайті в куті на ваш вибір.','Switcher Location'=>'Розташування перемикача','Apply a Template'=>'Застосувати шаблон','You can customize the design later'=>'Ви зможете налаштувати дизайн пізніше','Default Template'=>'Шаблон за замовчуванням','Default'=>'За замовчуванням','Dark Template'=>'Темний шаблон','Border Template'=>'Шаблон з рамкою','Border'=>'Рамка','Transparent Template'=>'Прозорий шаблон','Transparent'=>'Прозорий','Welcome to TranslatePress'=>'Ласкаво просимо до TranslatePress','Quick guided setup to configure TranslatePress in no time!'=>'Швидке кероване налаштування, щоб за мить налаштувати TranslatePress!','It takes less than a minute.'=>'Це займає менше хвилини.','Scanning item %1$d of %2$d...'=>'Сканування елемента %1$d з %2$d...','Manually translated'=>'Перекладено вручну','Automatically translated'=>'Перекладено автоматично','Gettext file translation'=>'Переклад файлів Gettext','Not translated'=>'Не перекладено','Bulk Actions'=>'Масові дії','Delete entries'=>'Видалити записи','Filter'=>'Фільтр','Clear filters'=>'Очистити фільтри','Language'=>'Мова','Add New'=>'Додати новий','Rescan plugins and theme for strings'=>'Повторно сканувати плагіни та тему на рядки','Scanning plugins and theme for strings...'=>'Сканування плагінів та теми на рядки...','Plugins and theme scan is complete'=>'Сканування плагінів та теми завершено','Plugins and theme scan did not finish due to an error'=>'Сканування плагінів та теми не завершено через помилку','Import / Export'=>'Імпорт / Експорт','See More'=>'Показати більше','See Less'=>'Показати менше','Apply'=>'Застосувати','No strings match your query.'=>'Жоден рядок не відповідає вашому запиту.','Try to rescan plugins and theme for strings.'=>'Спробуйте повторно сканувати плагіни та тему на рядки.','An error occurred while loading results. Most likely you were logged out. Reload page?'=>'Під час завантаження результатів сталася помилка. Ймовірно, ви вийшли з системи. Перезавантажити сторінку?','found in translation'=>'знайдено в перекладі','Select All'=>'Вибрати все','Select Visible'=>'Вибрати видимі','You are about to perform this action on all the strings matching your filter, not just the visibly checked. To perform the action only to the visible strings click "Select Visible" from the table header dropdown.'=>'Ви збираєтеся виконати цю дію з усіма рядками, що відповідають вашому фільтру, а не лише з видимими позначеними. Щоб виконати дію лише з видимими рядками, натисніть «Вибрати видимі» у спадному меню заголовка таблиці.','You are about to perform this action only on the visible strings. To perform the action on all the strings matching the filter click "Select All" from the table header dropdown.'=>'Ви збираєтеся виконати цю дію лише з видимими рядками. Щоб виконати дію з усіма рядками, що відповідають фільтру, натисніть «Вибрати всі» у спадному меню заголовка таблиці.','To continue please type the word:'=>'Щоб продовжити, введіть слово:','The word typed was incorrect. Action was cancelled.'=>'Введене слово невірне. Дію скасовано.','Warning: This action cannot be undone. Deleting a string will remove its current translation. The original string will appear again in this interface after TranslatePress detects it. This action is NOT equivalent to excluding the string from being translated again.'=>'Попередження: цю дію неможливо скасувати. Видалення рядка призведе до видалення його поточного перекладу. Оригінальний рядок знову з’явиться в цьому інтерфейсі після того, як його виявить TranslatePress. Ця дія НЕ є еквівалентною виключенню рядка з подальшого перекладу.','%d original entries and their translations were deleted.'=>'%d оригінальних записів та їхніх перекладів було видалено.','Navigate to next page'=>'Перейти на наступну сторінку','Navigate to previous page'=>'Перейти на попередню сторінку','Navigate to first page'=>'Перейти на першу сторінку','Navigate to last page'=>'Перейти на останню сторінку','Type a page number to navigate to'=>'Введіть номер сторінки для переходу','Incorrect page number. Type a page number between 1 and total number of pages'=>'Неправильний номер сторінки. Введіть номер сторінки від 1 до загальної кількості сторінок','Search original and translated strings containing typed keywords while also matching selected filters. Place string in quotes for exact match: "string"'=>'Шукати оригінальні та перекладені рядки, що містять введені ключові слова, водночас відповідаючи вибраним фільтрам. Візьміть рядок у лапки для точного збігу: "рядок"','Filter strings according to selected translation status, filters and keywords and selected filters'=>'Фільтрувати рядки відповідно до вибраного статусу перекладу, фільтрів і ключових слів, а також вибраних фільтрів','Removes selected filters'=>'Видаляє вибрані фільтри','See options for selecting all strings'=>'Переглянути параметри для вибору всіх рядків','Click to sort strings by this column'=>'Натисніть, щоб сортувати рядки за цим стовпцем','The ID of the WordPress post where this string was detected. Empty if the string is not associated with a specific post.'=>'ID запису WordPress, де було виявлено цей рядок. Порожнє, якщо рядок не пов\'язаний із конкретним записом.','Language in which the translation status filter applies. Leave unselected for the translation status to apply to ANY language'=>'Мова, до якої застосовується фільтр статусу перекладу. Залиште невибраною, щоб статус перекладу застосовувався до БУДЬ-ЯКОЇ мови','Search'=>'Пошук','Slugs that are not found in either one of the other categories.'=>'Slug, які не знайдені в жодній з інших категорій.','Plugins and Theme String Translation'=>'Переклад рядків плагінів і теми','Gettext'=>'Gettext','Search Gettext Strings'=>'Пошук рядків Gettext','Original String'=>'Оригінальний рядок','Filter by domain'=>'Фільтрувати за доменом','Filter by type'=>'Фільтрувати за типом','Email text'=>'Текст листа','Emails String Translation'=>'Переклад рядків електронної пошти','Emails'=>'Листи','Search Email Strings'=>'Пошук рядків електронної пошти','User Inputted String Translation'=>'Переклад рядків, введених користувачем','Regular'=>'Звичайні','Search Regular Strings'=>'Пошук звичайних рядків','Filter by Translation Block'=>'Фільтрувати за блоком перекладу','String Translation Editor'=>'Редактор перекладу рядків','Every minute'=>'Щохвилини','Could not load the background task.'=>'Не вдалося завантажити фонове завдання.','Waiting to start background processing...'=>'Очікування запуску фонової обробки...','Background processing could not start.'=>'Не вдалося запустити фонову обробку.','Background processing completed.'=>'Фонову обробку завершено.','A previous batch item failed.'=>'Попередній елемент пакета завершився помилкою.','TranslatePress background processing did not complete successfully.'=>'Фонова обробка TranslatePress не завершилася успішно.','Error: %s'=>'Помилка: %s','You do not have permission to view this task status.'=>'У вас немає дозволу на перегляд статусу цього завдання.','Invalid batch task.'=>'Недійсне завдання пакета.','TranslatePress is processing a background task.'=>'TranslatePress виконує фонове завдання.','TranslatePress background processing completed successfully.'=>'Фонову обробку TranslatePress успішно завершено.','Processing %s...'=>'Обробка %s...','%s is optimizing gettext database tables in the background. Translations continue to work while this runs.'=>'%s оптимізує таблиці бази даних gettext у фоновому режимі. Переклади продовжують працювати під час виконання.','TranslatePress gettext database optimization completed successfully.'=>'Оптимізацію бази даних gettext TranslatePress успішно завершено.','TranslatePress has detected and cleaned up some failed translation entries in your database following %s. No further action is required.'=>'TranslatePress виявив та очистив деякі невдалі записи перекладу у вашій базі даних після %s. Подальших дій не потрібно.','an isolated incident'=>'поодинокий випадок','Update aborted! Unknown gettext lookup hash migration phase: %s.'=>'Оновлення перервано! Невідома фаза міграції хешу пошуку gettext: %s.','Update aborted! Could not find an available gettext original_id index name for table %s.'=>'Оновлення перервано! Не вдалося знайти доступну назву індексу original_id gettext для таблиці %s.','Update aborted! Gettext lookup hash migration cannot process invalid ID %1$d in table %2$s. Repair the table ID schema and retry.'=>'Оновлення перервано! Міграція хешу пошуку gettext не може обробити недійсний ID %1$d у таблиці %2$s. Відновіть схему ID таблиці та повторіть спробу.','Update aborted! Table %1$s still references %2$d duplicate gettext original ids.'=>'Оновлення перервано! Таблиця %1$s досі посилається на %2$d дубльованих ідентифікаторів оригіналу gettext.','Update aborted! Gettext original meta still references %d duplicate original ids.'=>'Оновлення перервано! Метадані оригіналу gettext досі посилаються на %d дубльованих ідентифікаторів оригіналу.','Gettext database optimization completed.'=>'Оптимізацію бази даних gettext завершено.','Deduplicating gettext translation tables...'=>'Дедублікація таблиць перекладів gettext...','Migrating gettext original lookup hashes...'=>'Міграція хешів пошуку оригіналів gettext...','Preparing the gettext originals lookup index...'=>'Підготовка пошукового індексу оригіналів Gettext...','Updating gettext runtime statuses...'=>'Оновлення статусів часу виконання Gettext...','Finishing gettext database optimization...'=>'Завершення оптимізації бази даних Gettext...','Updating gettext runtime statuses for language %s...'=>'Оновлення статусів часу виконання Gettext для мови %s...','Resolving missing gettext original ids in %s...'=>'Вирішення відсутніх ідентифікаторів оригіналів Gettext у %s...','Preparing gettext table %s...'=>'Підготовка таблиці Gettext %s...','Removing invalid gettext rows from %s...'=>'Видалення недійсних рядків Gettext із %s...','Prepared gettext original ids in %s...'=>'Підготовлено ідентифікатори оригіналів Gettext у %s...','Normalizing plural forms in %s...'=>'Нормалізація форм множини у %s...','Processing duplicate gettext rows in %s...'=>'Обробка дублікатів рядків Gettext у %s...','Building duplicate gettext map for %s...'=>'Створення карти дублікатів Gettext для %s...','Verifying gettext table %s...'=>'Перевірка таблиці Gettext %s...','Deleting duplicate gettext rows from %s...'=>'Видалення дублікатів рядків Gettext із %s...','Rechecking duplicate gettext rows in %s...'=>'Повторна перевірка дублікатів рядків Gettext у %s...','Adding unique gettext index for %s...'=>'Додавання унікального індексу Gettext для %s...','Finished gettext table %s.'=>'Обробку таблиці Gettext %s завершено.','License'=>'Ліцензія','Your License Key is valid.'=>'Ваш ліцензійний ключ дійсний.','Your License Key is invalid.'=>'Ваш ліцензійний ключ недійсний.','Your License has expired.'=>'Термін дії вашої ліцензії минув.','Deactivate License'=>'Деактивувати ліцензію','Add a license key'=>'Додати ліцензійний ключ','License Key'=>'Ліцензійний ключ','Manage your license in your %1$s.'=>'Керуйте своєю ліцензією в розділі %1$s.','Don’t have a TranslatePress AI License Key?'=>'Не маєте ліцензійного ключа TranslatePress AI?','Get a free License Today'=>'Отримати безкоштовну ліцензію сьогодні','Add your License Key'=>'Додайте свій ліцензійний ключ','Add your License Key to unlock all premium features. Find the License Key in your'=>'Додайте свій ліцензійний ключ, щоб розблокувати всі преміум функції. Знайдіть ліцензійний ключ у вашому','Your license is valid and active.'=>'Ваша ліцензія дійсна та активна.','TranslatePress License'=>'Ліцензія TranslatePress','In order to enable Automatic Translation using TranslatePress AI, you need a license key by creating a free account.'=>'Щоб увімкнути автоматичний переклад за допомогою TranslatePress AI, вам потрібен ліцензійний ключ, який можна отримати, створивши безкоштовний обліковий запис.','In order to enable Automatic Translation using TranslatePress AI, please enter your license key from'=>'Щоб увімкнути автоматичний переклад за допомогою TranslatePress AI, введіть ваш ліцензійний ключ із','Get Your Free TranslatePress AI License'=>'Отримайте безкоштовну ліцензію TranslatePress AI','Generate License'=>'Згенерувати ліцензію','Get a Free AI License'=>'Отримати безкоштовну AI-ліцензію','This website is already activated under a free license. Each website can only use one free license.'=>'Цей веб-сайт уже активовано за безкоштовною ліцензією. Кожен веб-сайт може використовувати лише одну безкоштовну ліцензію.','This website is already activated under a free license. Each website can only use one free license. Please upgrade to a premium plan for more TranslatePress AI words from %1$s your account %2$s.'=>'Цей сайт уже активовано за безкоштовною ліцензією. Кожен сайт може використовувати лише одну безкоштовну ліцензію. Будь ласка, перейдіть на преміум-план, щоб отримати більше слів TranslatePress AI з %1$s вашого облікового запису %2$s.','Debug Data for License Checking'=>'Дані для налагодження перевірки ліцензії','Debug Data for License Activation'=>'Дані для налагодження активації ліцензії','Please install and activate the TranslatePress - Multilingual plugin'=>'Будь ласка, встановіть та активуйте плагін TranslatePress - Multilingual','Please update the TranslatePress - Multilingual plugin to version %1$s or higher to ensure %2$s functions correctly.'=>'Будь ласка, оновіть плагін TranslatePress - Multilingual до версії %1$s або вище, щоб забезпечити коректну роботу %2$s.','Please update TranslatePress - Multilingual to version %2$s or newer. Your currently installed version of TranslatePress - Multilingual is no longer compatible with the current version of %1$s.'=>'Будь ласка, оновіть TranslatePress - Multilingual до версії %2$s або новішої. Ваша поточна встановлена версія TranslatePress - Multilingual більше не сумісна з поточною версією %1$s.','All TranslatePress functionalities are disabled until then.'=>'Усі функціональні можливості TranslatePress вимкнені доти.','Update Now'=>'Оновити зараз','This TranslatePress add-on has been migrated to the main plugin and is no longer used. You can delete it.'=>'Це розширення TranslatePress було перенесено до основного плагіна і більше не використовується. Ви можете видалити його.','<strong>TranslatePress</strong> requires at least PHP version 5.6.20+ to run. It is the <a href="%s">minimum requirement of the latest WordPress version</a>. Please contact your server administrator to update your PHP version.'=>'<strong>TranslatePress</strong> потребує принаймні PHP версії 5.6.20+ для роботи. Це <a href="%s">мінімальна вимога останньої версії WordPress</a>. Будь ласка, зв\'яжіться з адміністратором вашого сервера, щоб оновити версію PHP.','TranslatePress Add-ons'=>'Доповнення TranslatePress','You must first purchase this version to have access to the addon %1$shere%2$s'=>'Спочатку ви повинні придбати цю версію, щоб отримати доступ до доповнення %1$sтут%2$s','You need an active license to have access to the addon. Renew or purchase a new one %1$shere%2$s.'=>'Для доступу до додатка потрібна активна ліцензія. Поновіть або придбайте нову %1$sтут%2$s.','Please %1$senter your license%2$s key first, to activate this addon.'=>'Будь ласка, спочатку %1$sвведіть ліцензійний%2$s ключ, щоб активувати цей додаток.','SEO Pack (Legacy)'=>'SEO Pack (Застарілий)','SEO support for page slug, page title, description and facebook and twitter social graph information. The HTML lang attribute is properly set.'=>'Підтримка SEO для slug сторінки, заголовка сторінки, опису та інформації соціального графа facebook і twitter. Атрибут HTML lang встановлено правильно.','Recommended Plugins'=>'Рекомендовані плагіни','A short list of plugins you can use to extend your website.'=>'Короткий список плагінів, які ви можете використати для розширення вашого веб-сайту.','Profile Builder'=>'Profile Builder','Capture more user information on the registration form with the help of Profile Builder\'s custom user profile fields and/or add an Email Confirmation process to verify your customers accounts.'=>'Збирайте більше інформації про користувачів у формі реєстрації за допомогою спеціальних полів профілю Profile Builder та/або додайте процес підтвердження електронної пошти, щоб верифікувати облікові записи ваших клієнтів.','Paid Member Subscriptions'=>'Paid Member Subscriptions','Accept user payments, create subscription plans and restrict content on your membership site.'=>'Приймайте платежі від користувачів, створюйте плани передплати та обмежуйте доступ до контенту на вашому сайті членства.','WP Webhooks Automator'=>'WP Webhooks Automator','Create no-code automations and workflows on your WordPress site. Easily connect your plugins, sites and apps together.'=>'Створюйте автоматизації та робочі процеси без коду на вашому сайті WordPress. Легко з’єднуйте свої плагіни, сайти та додатки між собою.','Save Changes'=>'Зберегти зміни','Account Page'=>'Сторінка облікового запису','You can get one for %1$sfree%2$s, by creating a free account. It includes:'=>'Ви можете отримати його %1$sбезкоштовно%2$s, створивши безкоштовний обліковий запис. Це включає:','Debug Information'=>'Інформація для налагодження','Get more AI words and unlock all features with TranslatePress Pro.'=>'Отримайте більше слів для автоматичного перекладу та розблокуйте всі функції за допомогою TranslatePress Pro.','Already purchased a Premium version?'=>'Вже придбали преміум-версію?','Go to your %1$s'=>'Перейдіть до вашого %1$s','TranslatePress.com Account'=>'Обліковий запис TranslatePress.com','Download & Install the Pro plugin'=>'Завантажити та встановити плагін Pro','Learn More'=>'Докладніше','TranslatePress Errors'=>'Помилки TranslatePress','There are no logged errors.'=>'Немає зареєстрованих помилок.','WordPress Translation Plugin'=>'Плагін перекладу для WordPress','Back to Glossary'=>'Назад до глосарія','Search Existing Translations'=>'Пошук наявних перекладів','Search the existing dictionary entries to see how a term is currently translated in each language.'=>'Пошукайте в наявних записах словника, щоб дізнатися, як термін перекладено кожною мовою.','To fully explore all the translations, use %s.'=>'Щоб повністю переглянути всі переклади, скористайтеся %s.','Search existing translations'=>'Шукати наявні переклади','Replace Existing Translations'=>'Замінити наявні переклади','The requested glossary term could not be found. It may have been deleted.'=>'Запитаний термін глосарія не знайдено. Можливо, його було видалено.','&laquo; Back to Glossary'=>'&laquo; Назад до глосарія','For each language, enter the current (existing) translation you want to find; every case-insensitive occurrence in the stored translations will be replaced with the new translation, keeping the original capitalization.'=>'Для кожної мови введіть поточний (наявний) переклад, який ви хочете знайти; кожне входження без урахування регістру в збережених перекладах буде замінено на новий переклад із збереженням оригінального написання.','Leaving a language field empty will skip that language entirely (no changes will be made for it). Only one existing translation per language can be entered at a time. If you have multiple translations to replace for the same language, simply run the replacement again with the next value.'=>'Якщо залишити поле мови порожнім, цю мову буде повністю пропущено (жодних змін для неї не буде внесено). Одночасно можна ввести лише один наявний переклад для кожної мови. Якщо вам потрібно замінити кілька перекладів для однієї мови, просто запустіть заміну знову з наступним значенням.','The "Existing translation" is not the term in the default language, but rather the already existing wrong translation you want to correct.'=>'«Наявний переклад» — це не термін мовою за замовчуванням, а вже наявний неправильний переклад, який ви хочете виправити.','Existing translation'=>'Наявний переклад','New translation'=>'Новий переклад','Replace in existing translations'=>'Замінити в наявних перекладах','Glossary is available only with the TranslatePress AI engine.'=>'Глосарій доступний лише з рушієм TranslatePress AI.','Select the %s automatic translation engine to add and manage glossary terms. For other translation engines (such as DeepL or Google Translate), glossary functions are available in the translation provider’s dashboard.'=>'Виберіть автоматичний рушій перекладу %s, щоб додавати та керувати термінами глосарія. Для інших рушіїв перекладу (таких як DeepL або Google Translate) функції глосарія доступні в панелі керування постачальника перекладу.','Add Glossary Term'=>'Додати термін глосарія','Define words or phrases that should not be translated automatically, and optionally provide replacements per language.'=>'Визначте слова чи фрази, які не слід перекладати автоматично, і за потреби вкажіть заміни для кожної мови.','The original word or phrase in the default language.'=>'Оригінальне слово чи фраза мовою за замовчуванням.','Add Term'=>'Додати термін','Search glossary terms'=>'Шукати терміни глосарія','Search terms'=>'Терміни для пошуку','Search Glossary'=>'Шукати в глосарії','Loading…'=>'Завантаження…','To edit existing translations, use the %s.'=>'Щоб редагувати наявні переклади, скористайтеся %s.','Language Switcher update notice'=>'Повідомлення про оновлення перемикача мов','Legacy language switcher is currently enabled'=>'Зараз увімкнено застарілий перемикач мов','We’ve upgraded the switcher for richer customization and a better user experience.<br>In order to use the new configurator, turn off <strong>Load legacy language switcher</strong>.'=>'Ми оновили перемикач для розширеного налаштування та кращого досвіду користувачів.<br>Щоб використовувати новий конфігуратор, вимкніть <strong>Завантажувати застарілий перемикач мов</strong>.','Note: You can switch back anytime from <strong>Advanced Settings → <a href="%s">Troubleshooting</a></strong>.'=>'Примітка: Ви можете повернутися будь-коли з <strong>Розширені налаштування → <a href="%s">Вирішення проблем</a></strong>.','Enable the new switcher'=>'Увімкнути новий перемикач','Get a translation volume estimate with a detailed breakdown per page'=>'Отримайте оцінку обсягу перекладу з детальним розбиттям за сторінками','Find how many translatable words are on your website'=>'Дізнайтеся, скільки слів для перекладу є на вашому сайті','<strong>DeepL</strong> automatic translation is available as a <a href="%1$s" target="_blank" title="%2$s">%2$s</a>.'=>'Автоматичний переклад за допомогою <strong>DeepL</strong> доступний як <a href="%1$s" target="_blank" title="%2$s">%2$s</a>.','By upgrading you\'ll get access to all paid add-ons, premium support and help fund the future development of TranslatePress.'=>'Оновившись, ви отримаєте доступ до всіх платних додатків, преміальної підтримки та допоможете фінансувати подальший розвиток TranslatePress.','To use <strong>DeepL</strong> for automatic translation, activate this Pro add-on from the <a href="%1$s" target="_self" title="%2$s">%2$s</a>.'=>'Щоб використовувати <strong>DeepL</strong> для автоматичного перекладу, активуйте цей Pro-додаток на сторінці <a href="%1$s" target="_self" title="%2$s">%2$s</a>.','Please note that DeepL API usage is paid separately. See <a href="https://www.deepl.com/pro.html#developer">DeepL pricing information</a>.'=>'Зверніть увагу, що використання DeepL API оплачується окремо. Дивіться <a href="https://www.deepl.com/pro.html#developer">інформацію про ціни DeepL</a>.','TranslatePress Pro Add-ons'=>'Додатки TranslatePress Pro','Test API credentials'=>'Перевірити облікові дані API','Check if the selected translation engine is configured correctly.'=>'Перевірити, чи правильно налаштований обраний механізм перекладу.','Alternative Engines'=>'Альтернативні механізми','More info'=>'Докладніше','Switch to TranslatePress AI'=>'Перейти на TranslatePress AI','Integrate machine translation directly with your WordPress website.'=>'Інтегрувати машинний переклад безпосередньо з вашим сайтом WordPress.','Choose which engine you want to use in order to %1$s automatically translate your website.'=>'Оберіть механізм, який ви хочете використовувати, щоб %1$s автоматично перекласти ваш сайт.','Automatically Translate Slugs'=>'Автоматично перекладати slug','Generate automatic translations of slugs for posts, pages and Custom Post Types.<br/>The slugs will be automatically translated starting with the second refresh of each page.'=>'Автоматично генерувати переклади slug для записів, сторінок і користувацьких типів записів.<br/>Slug будуть автоматично перекладатися починаючи з другого оновлення кожної сторінки.','This feature is only available in the paid version. Upgrade TranslatePress and unlock more premium features.'=>'Ця функція доступна лише в платній версії. Оновіть TranslatePress та розблокуйте більше преміум-функцій.','Requires <a href="%s" title="TranslatePress Add-on SEO Pack documentation" target="_blank">SEO Pack Add-on</a> to be installed and activated.'=>'Потрібно встановити та активувати <a href="%s" title="TranslatePress Add-on SEO Pack documentation" target="_blank">доповнення SEO Pack</a>.','Automatic Translation Settings'=>'Налаштування автоматичного перекладу','AI Words Low Notification'=>'Сповіщення про низьку кількість AI-слів','Receive an email notification when your TranslatePress AI word count drops below the specified threshold.'=>'Отримувати сповіщення електронною поштою, коли кількість слів TranslatePress AI опуститься нижче вказаного порогу.','This feature is only available when using the TranslatePress AI translation engine.'=>'Ця функція доступна лише при використанні механізму перекладу TranslatePress AI.','Notification Email'=>'Email для сповіщень','The email address where the low AI words notification will be sent.'=>'Адреса електронної пошти, на яку надходитиме сповіщення про низьку кількість AI-слів.','Word Threshold'=>'Поріг слів','words'=>'слів','You will be notified when remaining AI words drop below this number.'=>'Ви отримаєте сповіщення, коли залишок AI-слів опуститься нижче цього числа.','Block Crawlers'=>'Блокувати краулери','Block crawlers from triggering automatic translations on your website.<br>This will not prevent crawlers from accessing this site\'s pages.'=>'Заборонити краулерам ініціювати автоматичний переклад на вашому сайті.<br>Це не завадить краулерам отримувати доступ до сторінок цього сайту.','Limit machine translation / characters per day'=>'Обмеження машинного перекладу / символів на день','Add a limit to the number of automatically translated characters so you can better budget your project.'=>'Встановіть ліміт кількості символів автоматичного перекладу, щоб краще планувати бюджет вашого проєкту.','characters per day'=>'символів на день','Today\'s Character Count: '=>'Кількість символів за сьогодні: ','Log machine translation queries.'=>'Реєструвати запити машинного перекладу.','Only enable for testing purposes. Can impact performance.<br>All records are stored in the wp_trp_machine_translation_log database table. Use a plugin like <a href="https://wordpress.org/plugins/wp-data-access/" target="_blank">WP Data Access</a> to browse the logs or directly from your database manager (PHPMyAdmin, etc.)'=>'Увімкніть лише для тестування. Може вплинути на продуктивність.<br>Усі записи зберігаються в таблиці бази даних wp_trp_machine_translation_log. Використовуйте плагін на кшталт <a href="https://wordpress.org/plugins/wp-data-access/" target="_blank">WP Data Access</a>, щоб переглядати журнали, або безпосередньо з вашого менеджера баз даних (PHPMyAdmin тощо).','Test API Credentials'=>'Перевірити облікові дані API','HTTP Referrer: '=>'HTTP Referrer: ','Use this HTTP Referrer if the API lets you restrict key usage from its Dashboard.'=>'Використовуйте цей HTTP Referrer, якщо API дозволяє обмежити використання ключа з його панелі керування.','Request URL'=>'URL запиту','Request Headers'=>'Заголовки запиту','Request Body'=>'Тіло запиту','Response'=>'Відповідь','Response Body'=>'Тіло відповіді','Entire Response From wp_remote_get():'=>'Повна відповідь від wp_remote_get():','Select the languages you wish to make your website available in.'=>'Виберіть мови, якими ви хочете зробити свій вебсайт доступним.','Formality'=>'Формальність','Code'=>'Код','Formal'=>'Формальний','Informal'=>'Неформальний','This language does not support formality. '=>'Ця мова не підтримує формальність. ','Are you sure you want to remove this language?'=>'Ви впевнені, що хочете видалити цю мову?','Custom Languages'=>'Користувацькі мови','Adding more than two languages is a paid feature. Upgrade TranslatePress and unlock more premium features.'=>'Додавання більше ніж двох мов — платна функція. Оновіть TranslatePress і розблокуйте більше преміум-функцій.','Please %1$senter your license%2$s key first to add more languages.'=>'Будь ласка, спочатку %1$sвведіть ваш ліцензійний%2$s ключ, щоб додати більше мов.','You need an active license to add more languages. Verify in your %1$saccount%2$s that your license is valid'=>'Вам потрібна активна ліцензія, щоб додати більше мов. Перевірте у вашому %1$sобліковому записі%2$s, що ваша ліцензія дійсна.','To Add more languages activate the Multiple Languages Addon'=>'Щоб додати більше мов, активуйте додаток Multiple Languages','Website Languages'=>'Мови сайту','WARNING. Changing the default language will invalidate existing translations.'=>'УВАГА. Зміна мови за замовчуванням зробить наявні переклади недійсними.','Even changing from en_US to en_GB, because they are treated as two different languages.'=>'Навіть зміна з en_US на en_GB, оскільки їх обробляють як дві різні мови.','In most cases changing the default flag is all it is needed: '=>'У більшості випадків достатньо змінити прапорець за замовчуванням: ','replace the default flag'=>'замінити прапорець за замовчуванням','Re-run Setup Wizard'=>'Повторно запустити майстер налаштування','The Setup wizard allows you to quickly setup TranslatePress. You can initiate it at any time.'=>'Майстер налаштування дозволяє швидко налаштувати TranslatePress. Ви можете запустити його в будь-який час.','Language Settings'=>'Налаштування мов','Use Native language name'=>'Використовувати рідну назву мови','Check if you want to display languages in their native names. Otherwise, languages will be displayed in English.'=>'Позначте, якщо хочете відображати мови їхніми рідними назвами. Інакше мови відображатимуться англійською.','Use a subdirectory for the default language'=>'Використовувати підкаталог для мови за замовчуванням','Check if you want to add the subdirectory in the URL for the default language.</br>By checking this option, the default language seen by website visitors will become the first one in the "All Languages" list.'=>'Позначте, якщо хочете додати підкаталог до URL-адреси для мови за замовчуванням.</br>Якщо позначити цей параметр, мовою за замовчуванням для відвідувачів веб-сайту стане перша у списку «Усі мови».','Force language in custom links'=>'Примусово встановлювати мову в користувацьких посиланнях','Select Yes if you want to force custom links without language encoding to keep the currently selected language.'=>'Виберіть «Так», якщо хочете, щоб користувацькі посилання без мовного кодування зберігали поточну вибрану мову.','Shortcode '=>'Shortcode ','Use shortcode on any page or widget.'=>'Використовуйте shortcode на будь-якій сторінці або у віджеті.','You can also add the <a href="%s" title="Language Switcher Block Documentation">Language Switcher Block</a> in the WP Gutenberg Editor.'=>'Ви також можете додати <a href="%s" title="Language Switcher Block Documentation">блок перемикача мов</a> у редакторі WP Gutenberg.','Menu item'=>'Пункт меню','Go to  %1$s Appearance -> Menus%2$s to add languages to the Language Switcher in any menu.'=>'Перейдіть до  %1$s Зовнішній вигляд -> Меню%2$s, щоб додати мови до перемикача мов у будь-якому меню.','Learn more in our documentation.'=>'Дізнайтеся більше в нашій документації.','Floating language selection'=>'Плаваючий вибір мови','Add a floating dropdown that follows the user on every page.'=>'Додайте плаваючий випадаючий список, який супроводжує користувача на кожній сторінці.','Show "Powered by TranslatePress"'=>'Показувати "Powered by TranslatePress"','Show the small "Powered by TranslatePress" label in the floater language switcher.'=>'Показувати маленький напис "Powered by TranslatePress" у плаваючому перемикачі мов.','5 Days to Better Multilingual Websites'=>'5 днів до кращих багатомовних веб-сайтів','%sJoin our FREE & EXCLUSIVE onboarding course%s and learn how to grow your multilingual traffic, reach international markets, and save time & money while getting the most out of TranslatePress!'=>'%sПриєднуйтесь до нашого БЕЗКОШТОВНОГО та ЕКСКЛЮЗИВНОГО вступного курсу%s та дізнайтеся, як збільшувати багатомовний трафік, виходити на міжнародні ринки та заощаджувати час і гроші, максимально використовуючи TranslatePress!','Invalid email address'=>'Неправильна адреса електронної пошти','Your email'=>'Ваша електронна пошта','Sign me up!'=>'Підписатися!','Sign up with your email address and receive a 5-part email guide to help you maximize the power of TranslatePress.'=>'Підпишіться, вказавши свою адресу електронної пошти, та отримайте 5-частинний електронний посібник, який допоможе вам максимально розкрити потенціал TranslatePress.','Dismiss email course notification'=>'Відхилити сповіщення про електронний курс','Hey %s,<br>Never miss an important update - opt in to our security and feature updates notifications, and non-sensitive diagnostic tracking.'=>'Привіт, %s,<br>Ніколи не пропускайте важливі оновлення - погодьтеся на отримання сповіщень про оновлення безпеки та функцій, а також на збір нечутливої діагностичної інформації.','Allow & Continue'=>'Дозволити та продовжити','Skip'=>'Пропустити','This will allow TranslatePress to:'=>'Це дозволить TranslatePress:','Your profile overview'=>'Огляд вашого профілю','Name and email address'=>'Ім\'я та адреса електронної пошти','Admin Notices'=>'Сповіщення адміністратора','Updates, announcements, marketing, no spam'=>'Оновлення, оголошення, маркетинг, без спаму','Plugin status & settings'=>'Статус і налаштування плагіна','Active, Deactivated, installed version and settings'=>'Активний, деактивований, встановлена версія та налаштування','Privacy Policy'=>'Політика конфіденційності','Terms of Service'=>'Умови використання','Support'=>'Підтримка','Add Extra AI Words'=>'Додати додаткові AI-слова','<strong>IMPORTANT NOTE:</strong> Before performing this action it is strongly recommended to first backup the database.'=>'<strong>ВАЖЛИВА ПРИМІТКА:</strong> Перед виконанням цієї дії наполегливо рекомендується спочатку створити резервну копію бази даних.','IMPORTANT: It is strongly recommended to first backup the database!! Are you sure you want to continue?'=>'ВАЖЛИВО: Наполегливо рекомендується спочатку створити резервну копію бази даних!! Ви впевнені, що хочете продовжити?','Operations to perform'=>'Операції для виконання','Remove CDATA for original and dictionary strings'=>'Видалити CDATA з оригінальних та словникових рядків','Removes CDATA from trp_original_strings and trp_dictionary_* tables.<br>This type of content should not be detected by TranslatePress. It might have been introduced in the database in older versions of the plugin.'=>'Видаляє CDATA з таблиць trp_original_strings та trp_dictionary_*.<br>Цей тип вмісту не повинен визначатися TranslatePress. Його могло бути додано до бази даних у старіших версіях плагіна.','Remove untranslated links from dictionary tables'=>'Видалити неперекладені посилання з таблиць словника','Removes untranslated links and images from all trp_dictionary_* tables. These tables contain translations for user-inputted strings such as post content, post title, menus etc.'=>'Видаляє неперекладені посилання та зображення з усіх таблиць trp_dictionary_*. Ці таблиці містять переклади для рядків, введених користувачем, таких як вміст запису, заголовок запису, меню тощо.','Remove duplicate rows for gettext strings'=>'Видалити дублікати для рядків gettext','Cleans up all trp_gettext_* tables of duplicate rows. These tables contain translations for themes and plugin strings.'=>'Очищає всі таблиці trp_gettext_* від дублікатів рядків. Ці таблиці містять переклади для рядків тем і плагінів.','Remove duplicate rows for dictionary strings'=>'Видалити дублікати для словникових рядків','Cleans up all trp_dictionary_* tables of duplicate rows. These tables contain translations for user-inputted strings such as post content, post title, menus etc.'=>'Очищає всі таблиці trp_dictionary_* від дублікатів рядків. Ці таблиці містять переклади для рядків, введених користувачем, таких як вміст запису, заголовок запису, меню тощо.','Remove duplicate rows for original dictionary strings'=>'Видалити дублікати для оригінальних словникових рядків','Cleans up all trp_original_strings table of duplicate rows. This table contains strings in the default language, without any translation.<br>The trp_original_meta table, which contains meta information that refers to the post parent’s ID, is also regenerated.<br>Such duplicates can appear in exceptional situations of unexpected behavior.'=>'Очищає таблицю trp_original_strings від дублікатів рядків. Ця таблиця містить рядки мовою за замовчуванням без жодних перекладів.<br>Таблиця trp_original_meta, яка містить метаінформацію, що посилається на ID батьківського запису, також буде регенерована.<br>Такі дублікати можуть з\'являтися в рідкісних випадках непередбачуваної поведінки.','Replace gettext strings that have original ID NULL with the correct original IDs'=>'Замінити рядки gettext, у яких оригінальний ID дорівнює NULL, правильними оригінальними ID','Fixes an edge case issue where some gettext strings have the original ID incorrectly set to NULL, causing problems in the Translation Editor.<br>This operation corrects the original IDs in the trp_gettext_* tables.<br>Only check this option if you encountered an issue in the Translation Editor where clicking the green pencil did not bring up the gettext string for translation in the left sidebar.<br>Otherwise, please leave this option unchecked because it\'s an intensive operation.'=>'Виправляє проблему в рідкісному випадку, коли деякі рядки gettext мають оригінальний ID неправильно встановлено як NULL, що спричиняє проблеми в редакторі перекладів.<br>Ця операція виправляє оригінальні ID в таблицях trp_gettext_*.<br>Позначте цю опцію, лише якщо ви зіткнулися з проблемою в редакторі перекладів, коли натискання зеленого олівця не відкривало рядок gettext для перекладу в лівій бічній панелі.<br>В іншому випадку залиште цю опцію непозначеною, оскільки це ресурсомістка операція.','Optimize Database'=>'Оптимізувати базу даних','TranslatePress Database Updater'=>'TranslatePress Database Updater','Updating TranslatePress tables. Please leave this window open.'=>'Оновлення таблиць TranslatePress. Будь ласка, залиште це вікно відкритим.','Open colour picker'=>'Відкрити вибір кольору','Enabled'=>'Увімкнено','Disabled'=>'Вимкнено','Write custom CSS here...'=>'Напишіть власний CSS тут...','Include'=>'Включити','Exclude'=>'Виключити','Content Restriction Mode'=>'Режим обмеження вмісту','No languages selected'=>'Мови не вибрано','Saving...'=>'Збереження...','Saved!'=>'Збережено!','Save changes'=>'Зберегти зміни','Revert to last saved values'=>'Відновити останні збережені значення','Revert changes'=>'Скасувати зміни','Restoring will revert to the last saved version and discard your current edits.'=>'Відновлення поверне до останньої збереженої версії та відкине поточні зміни.','Revert'=>'Відновити','Keep editing'=>'Продовжити редагування','Are you sure you want to apply the <strong>%s</strong> preset?'=>'Ви впевнені, що хочете застосувати пресет <strong>%s</strong>?','It will override your current settings.'=>'Це замінить ваші поточні налаштування.','Apply preset'=>'Застосувати пресет','Apply %s preset'=>'Застосувати шаблон %s','Save failed'=>'Збереження не вдалося','English'=>'Англійська','Spanish'=>'Іспанська','French'=>'Французька','Minimal Light'=>'Мінімалістична світла','Dark Overlay'=>'Темне перекриття','Brand Blue'=>'Фірмовий синій','Bordered'=>'З рамкою','Popup Preview'=>'Попередній перегляд спливаючого вікна','User Language Detection Method'=>'Спосіб визначення мови користувача','Notification Behavior'=>'Поведінка сповіщень','Popup Content'=>'Вміст спливаючого вікна','Apply a preset'=>'Застосувати шаблон','Customize Design'=>'Налаштувати дизайн','Language detection'=>'Визначення мови','Select how the language should be detected for first time visitors.<br>The visitor\'s last displayed language will be remembered through cookies.'=>'Виберіть, як слід визначати мову для нових відвідувачів.<br>Остання показана мова відвідувача запам’ятовуватиметься за допомогою файлів cookie.','Popup display'=>'Відображення спливаючого вікна','Conditionally display popup based on language'=>'Умовне відображення спливаючого вікна залежно від мови','Popup Type'=>'Тип спливаючого вікна','Visitors will be redirected directly when a different preferred language is detected.'=>'Відвідувачів буде одразу перенаправлено при виявленні іншої бажаної мови.','Popup Text'=>'Текст спливаючого вікна','Button Text'=>'Текст кнопки','Close Button Text'=>'Текст кнопки закриття','Background color'=>'Колір тла','Text color'=>'Колір тексту','Button background color'=>'Колір фону кнопки','Button hover color'=>'Колір кнопки при наведенні','Button text color'=>'Колір тексту кнопки','Button border radius'=>'Радіус рамки кнопки','Close icon color'=>'Колір іконки закриття','Overlay color'=>'Колір оверлею','Entrance animation'=>'Анімація появи','Animation'=>'Анімація','Fade'=>'Проявлення','Slide from top'=>'Ковзання зверху','Slide from right'=>'Ковзання справа','Slide from bottom'=>'Ковзання знизу','Slide from left'=>'Ковзання зліва','Enable custom CSS'=>'Увімкнути власний CSS','No names'=>'Без назв','Show flags'=>'Показувати прапорці','Rectangle (4:3)'=>'Прямокутник (4:3)','Square (1:1)'=>'Квадрат (1:1)','Flag border radius'=>'Радіус рамки прапора','Switcher background'=>'Тло перемикача','Switcher hover background'=>'Тло перемикача при наведенні','Switcher text'=>'Текст перемикача','Switcher hover text'=>'Текст перемикача при наведенні','Switcher border'=>'Рамка перемикача','Switcher border width'=>'Товщина рамки перемикача','Switcher border radius'=>'Радіус заокруглення рамки перемикача','Hover over the language switcher to see it in action!'=>'Наведіть курсор на перемикач мов, щоб побачити його в дії!','Switcher Preview'=>'Попередній перегляд перемикача','Enable Floating Switcher'=>'Увімкнути плаваючий перемикач','Switcher is enabled'=>'Перемикач увімкнено','Switcher is disabled'=>'Перемикач вимкнено','Switcher Type'=>'Тип перемикача','Show languages as dropdown'=>'Показувати мови як випадний список','Show languages side by side'=>'Показувати мови поруч','Background hover color'=>'Колір тла при наведенні','Text hover color'=>'Колір тексту при наведенні','Switcher border color'=>'Колір рамки перемикача','Flag and text size'=>'Розмір прапорця та тексту','Flag icons shape'=>'Форма піктограм прапорців','Flag icons border radius'=>'Радіус заокруглення піктограм прапорців','Customize Layout'=>'Налаштувати макет','Show the small Powered by TranslatePress label in the language switcher.'=>'Показувати маленький напис «Powered by TranslatePress» у перемикачі мов.','You have unsaved changes. Leave anyway?'=>'У вас є незбережені зміни. Вийти все одно?','Switcher animations'=>'Анімації перемикача','Transforms the language switcher into a button showing the other available language, not the current one. <br> Only works when there are exactly two languages, the default one and a translation one.'=>'Перетворює перемикач мови на кнопку, яка показує іншу доступну мову, а не поточну. <br> Працює лише тоді, коли є рівно дві мови: типова та перекладена.','This option only works when exactly two languages are published.'=>'Ця опція працює лише тоді, коли опубліковано рівно дві мови.','Copied!'=>'Скопійовано!','Copy'=>'Копіювати','Use shortcode on any page or widget. You can also add the Language Switcher Block in the WP Gutenberg Editor.'=>'Використовуйте shortcode на будь-якій сторінці або у віджеті. Ви також можете додати блок перемикача мови у редакторі WP Gutenberg.','Shortcode'=>'shortcode','Additional Settings'=>'Додаткові налаштування','Open the language switcher shortcode by clicking on it instead of hovering. <br> Close it by clicking on it, anywhere else on the screen or by pressing the escape key. <br> This will affect only the shortcode language switcher.'=>'Відкривайте shortcode перемикача мови клацанням на ньому замість наведення. <br> Закривайте його клацанням на ньому, клацанням будь-де ще на екрані або натисканням клавіші Escape. <br> Це вплине лише на shortcode перемикача мови.','Menu Switcher Layout'=>'Макет перемикача в меню','Go to <a href="/wp-admin/nav-menus.php">Appearance → Menus</a> to add languages to the Language Switcher in any menu.<br> <a href="https://translatepress.com/docs/settings/language-switcher/?utm_source=tp-language-switcher&utm_medium=client-site&utm_campaign=ls-menu-item#menu-switcher" target="_blank">Learn more in our documentation.</a>'=>'Перейдіть у розділ <a href="/wp-admin/nav-menus.php">Зовнішній вигляд → Меню</a>, щоб додати мови до перемикача мови в будь-якому меню.<br> <a href="https://translatepress.com/docs/settings/language-switcher/?utm_source=tp-language-switcher&utm_medium=client-site&utm_campaign=ls-menu-item#menu-switcher" target="_blank">Докладніше в нашій документації.</a>','Choose in which languages to show the block.'=>'Виберіть, якими мовами показувати блок.','Choose from which languages the block is excluded.'=>'Виберіть, з яких мов блок виключено.','Select language(s)'=>'Виберіть мову (мови)','TranslatePress Language Restriction'=>'Обмеження мови TranslatePress','Language restrictions cannot be saved on a top-level Classic block. Convert it to blocks or place it inside a Group block first.'=>'Мовні обмеження не можна зберегти в блоці Classic верхнього рівня. Перетворіть його на блоки або спочатку помістіть у блок Group.','page 1 of 3of'=>'/','Untranslated in this languagein'=>'на','Verbiage for the DeepL Pro Add-onAddons tab'=>'Вкладка додатків','Verbiage for the DeepL Pro Add-onTranslatePress Pro Add-on'=>'TranslatePress Pro Add-on','block titleLanguage Switcher'=>'Перемикач мови','block descriptionDisplays the Language Switcher.'=>'Відображає перемикач мови.','block keywordLanguage Switcher'=>'Перемикач мови','block keywordTranslate'=>'Перекласти','block keywordTranslatePress'=>'TranslatePress','block keywordLanguage Names'=>'Назви мов','block keywordFlags'=>'Прапори']];